window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26771798"]={"book":{"id":26771798,"title":"凸法则","author":"[美]山姆•洪恩","translator":"丁美龄","publisher":"长江文艺出版社","pubdate":"2016-5","isbn":"9787535487186","tags":["沟通","方法论","技巧","沟通类的书","好书","值得一读","心理学","我想读这本书","成长"],"memCount":14},"np":1,"pb":[18],"idx":[{"i":11193,"t":"用一句话在开场吸引人注意力","l":"TF1-2","c":"程硕","g":1,"p":1},{"i":11144,"t":"互动式自我介绍","l":"TF2-3","c":"锐群","g":1,"p":1},{"i":9295,"t":"拆书帮和RIA分享。","l":"TF1-1","c":"陈念媛","g":1,"p":1},{"i":8938,"t":"拆书帮介绍和RIA分享","l":"TF1-1","c":"陈念媛","g":1,"p":1},{"i":7296,"t":"拆书帮和RIA分享","l":"TF1-1","c":"陈念媛","g":1,"p":1},{"i":7196,"t":"如何设计一个引人注意的开场白","l":"TF2-3","c":"武小茉","g":1,"p":1},{"i":6336,"t":"一个句式帮助你快速吸引他人的注意力","l":"TF2-1","c":"葫芦大王","g":1,"p":1},{"i":5685,"t":"在演讲或介绍新观点时的开头牢牢吸引住听众的注意力","l":"TF2-4","c":"李小曼","g":1,"p":1},{"i":5227,"t":"用“襁褓”裹住谈话","l":"TF2-1","c":"师麦","g":1,"p":1},{"i":4525,"t":"如何与陌生人打开话题","l":"TF2-2","c":"孙晶晶","g":1,"p":1},{"i":3211,"t":"学会抓住“你的职业是什么”展开对话","l":"TF2-3","c":"甜橙大王","g":1,"p":1},{"i":3159,"t":"如何展开一场有趣的对话","l":"TF1-2","c":"什刹海","g":1,"p":1},{"i":2795,"t":"如何开始一次有意义并令对方感兴趣的对话","l":"TF1-2","c":"什刹海","g":1,"p":1},{"i":2761,"t":"余佳桐TF2-1定级","l":"TF2-1","c":"余佳桐","g":1,"p":1},{"i":1973,"t":"潇潇荷3-3定级","l":"TF3-3","c":"潇潇荷","g":1,"p":1},{"i":1971,"t":"潇潇荷3-1定级","l":"TF3-1","c":"潇潇荷","g":1,"p":1},{"i":1970,"t":"潇潇荷3-2定级","l":"TF3-2","c":"潇潇荷","g":1,"p":1},{"i":1319,"t":"使用开场白吸引别人注意力","l":"TF2-3","c":"太郎","g":1,"p":1}],"ms":[{"id":11193,"topic":"用一句话在开场吸引人注意力","learn_goal":"","remark":"你是否知道如何用一句话在开场瞬间吸引人注意力？想象一下，以往演讲或者讲课都枯燥寡淡的你，突然某一天，在上台时，竟然一瞬间抓住了所有人的注意力，是不是倍儿爽？其实，你不用想象，你看，我已经用一句话吸引了你的注意力。欢迎大家周五来听我讲讲这一秘诀~","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"程硕","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家好，我是cici，我的3个标签：1，产品经理，2，正在练习演讲和写作，3，希望在6月底前通过拆书家升级打怪。今天我的拆页是选自《凸法则》这本书，专门教你如何通过高效有趣的表达脱颖而出，作者是山姆·洪恩，他美国联邦政府沟通技巧内训课超级讲师、高端沟通策略师，而今天的拆页呢，正是这本书的核心内容之一，教你用三个步骤制作“你知道吗”开场白，瞬间吸引听众的注意力。\u003c/p>","ratings_count":1,"texts":[{"id":15106,"quote":"\u003cp>下面就是我们创造的开场白，不但帮助凯瑟琳赢得了认同和投资，而且帮她成为《商业周刊》2010年度最有前途的社会企业家之一。\u003c/p>\u003cp>你知道吗？现在每年接种疫苗有18亿。\u003c/p>\u003cp>你知道吗？接种那些疫苗时，有近乎一半使用重复利用的针头。\u003c/p>\u003cp>你知道吗？我们正在传播和延续我们试图预防的疾病。\u003c/p>\u003cp>想象一下，如果有一种针头是无痛的、一次性的，而且价格比当前的更便宜。\u003c/p>\u003cp>其实，你不用想象，我们已经创造出来了，这种针头就叫PharmaJet，正如这篇文章展示的这样……\u003c/p>\u003cp>接着她就朝着这个方向奔去了，你被调动起来了吗？和你一样，房间里的每个人也都被调动起来了。\u003c/p>\u003cp>让我们如实看待这个情况。PharmaJet团队过去这样开始他们的展示，解释他们是一个“皮下接种的医疗交付设备平台”。\u003c/p>\u003cp>哎呀！那样的介绍在一开场就失去吸引力了。可是，很多人都这样开始自己的交流，废话连篇的解释让观众简直无奈或只能轻叹一声。其实，观众这时已经得出“此问题难以理解”的结论了，于是转向更有趣或更紧急的事情。凯瑟琳有竞争优势，因为在1分钟里，她已经让所有人都感到好奇，渴望对主题有更多的了解。\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>这个拆页是用一个案例向我们展示了，主人公如何用你知道吗啊，想象一下，其实不用想象，我们已经，这样一个句式，瞬间抓住在场所有投资人的注意力，引发好奇，并最终获得认可和投资。\u003c/p>\u003cp>【一般人的做法】\u003c/p>\u003cp>这个方法和一般做法有什么不一样呢？我们想一下，一般人如果要介绍自己的产品，是怎么做的呢？是不是一上来，就从公司，产品特点，优势一步步讲起，这是很普通很无趣的做法，很难吸引别人的注意力，特别是在竞争者众多而时间又有限的场合，人家已经没有多少耐心了，你这种方式基本就是给他人做嫁衣，衬托他人的优秀。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>那具体怎么做呢？\u003c/p>\u003cp>它分为3个步骤：\u003c/p>\u003cp>第一步：用“你知道吗”的问句，引起人的好奇，点出这个问题下的痛点。\u003c/p>\u003cp>第二步：用“想象一下”引发人们想象问题解决后的场景或者结果\u003c/p>\u003cp>第三步：用“其实，不用想象，我们已经”，告诉大家，你这有解决办法，吸引大家继续听下去。\u003c/p>\u003cp>【A1】\u003c/p>\u003cp>为了更便于大家理解运用，我这里给大家举一个我自己的案例。\u003c/p>\u003cp>我上周二给我们客服部培训产品，和往常一样，我先介绍产品形态，再介绍产品优点，最后再和其他竞品对比，我发现大家听得一点都不积极，现场一片安静。\u003c/p>\u003cp>学了今天这个拆页，我认识到，我这种讲法太普通了，大家都已经听腻了，如果我能用今天这个开场白，那我可以这样讲：\u003c/p>\u003cp>你知道吗？人一生中患重疾的概率是72.18%。\u003c/p>\u003cp>你知道吗？大部分患癌患者，都会在1-3年后复发。而每年都会有大量患者因为治癌，卖房卖车一夜回到解放前。\u003c/p>\u003cp>想象一下，如果有一款产品，在客户不幸患癌，给付保额之后，如果客户1年后癌症复发或者持续存在，又可以再获赔1.2倍保额，而费率却只增加了几百钱，客户会不会喜欢呢？\u003c/p>\u003cp>其实，不用想象，我们即将上线这么一款产品。\u003c/p>\u003cp>这样，是不是听起来，效果更好呢，也更便于客服抓住重点呢。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这个句式非常适合用作演讲（或培训）开场白，也可以用来与别人沟通你的想法希望得到对方的认可的时候，除此之外呢，我认为它也可以用来写短文案。就比如，我这次的通告就是从这个三句式演变出来的，大家感兴趣的话，可以回头再看看。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：激活经验\u003c/strong>\u003c/p>\u003cp>通过这个拆页，我们知道了“你知道吗”三句式开场白，更容易吸引听众的注意力，并得到认可。那么，请我们每个人想一想，我们过去有没有类似的演讲或者培训的经历，或者向别人介绍产品或者跟别人沟通一个想法希望得到认可，我们是怎么做的呢？效果如何呢，请小组内讨论下，时间5分钟。我这里给大家分个组。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】：\u003c/strong>\u003c/p>\u003cp>学习者：甲老师\u003c/p>\u003cp>我经常跟人沟通亲子沟通到底有多重要，上周日，我按照平时的习惯，跟一个客户讲，亲子沟通真的很重要，特别是在青少年期间，一定要注意，否则孩子不仅得不到正向积极的教养，反而陷入逆反心态。\u003c/p>\u003cp>结果我的客户听完没什么感觉，好像这个事情跟他没有多大关系似的。\u003c/p>\u003cp>\u003cstrong>A1：催化应用\u003c/strong>\u003c/p>\u003cp>好的，感谢这位学习者带来他精彩的分享，学习是为了更好的运用，接下来请大家想一下，未来一周或者一个月你打算向别人推荐产品或者要说服对方接受你的提议，你会如何运用今天学到的开场白呢？请在便签上，写上时间，事件，你的具体做法，并预测下效果。时间是3分钟，然后交给我。\u003c/p>\u003cp>我举个例子，比如：你打算周六跟老公沟通想去云南旅游，你可以怎么用这个三句式打动他呢？\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】：\u003c/strong>\u003c/p>\u003cp>学习者：甲老师\u003c/p>\u003cp>时间：周日\u003c/p>\u003cp>人物：跟客户讨论亲子教育的重要性\u003c/p>\u003cp>事件：因为上周日跟客户A沟通亲子教育的重要性失败了，所以我这次将用“你知道吗三步法”再来跟他沟通一次。\u003c/p>\u003cp>具体做法：你知道吗？很多父母每天在跟孩子说话的过程中，其实都无意中对孩子造成了巨大的伤害，你知道吗？中国大多数父母其实都不知道自己的孩子在想什么，孩子又有着怎么样的需求，想象一下，如果以后你能从各种行为读懂你的孩子，你能用你的行为去影响你的孩子，你的孩子会因此长成一个更积极乐观聪明的孩子，未来你们会像最亲密的朋友一样沟通相处，那该多好。其实，你不用想象，你只需要花一点时间听我讲讲亲子教育到底是什么，以及我们该如何去做。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1616200465000,"updated_at":1616219420000,"ria":true},{"id":11144,"topic":"互动式自我介绍","learn_goal":"","remark":"自我介绍如何说得好听还让人印象深刻？互动式自我介绍法用提问创造互动，一思二问三引入，三个步骤让他人对你念念不忘。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"锐群","city":"三亚市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>【问好并自我介绍】\u003c/p>\u003cp>各位晚上好，欢迎来到今晚拆书现场，我是锐群，锐不可当的锐，物以类聚人以群分的群，我是三亚筹备分舵的发起人和召集人，也是一名拆书家。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>学习者通过本次学习，在需要回答“我是做什么工作”的场景里，可以初步运用拆页的方法，加工出互动式的介绍说辞。\u003cbr>\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>为了方便接下来的学习，咱们现场分个组。现在以我左手边的伙伴分为一组，右手边的伙伴分为另一组。\u003c/p>\u003cp>【FAB】\u003c/p>\u003cp>本次我们要一起来学习的是这本《凸法则》\u003c/p>\u003cp>F\u003c/p>\u003cp>作者山姆·洪恩，美国联邦政府沟通技巧内训课讲师，本书讲了8条主要来自商业场景的沟通原则，每条原则至少包含3个可操作的方法；\u003c/p>\u003cp>A\u003c/p>\u003cp>由于TA的内容主要取自商业场景，与同类书相比，针对性强，强调的是在沟通中增强影响力，在竞争中获得最大关注脱颖而出，其方法追求结果立竿见影；\u003cbr>\u003c/p>\u003cp>B1\u003c/p>\u003cp>对这本书进行学习之后，我们可以通过设计引人入胜的开场，一张口就能抓住听众的注意力；通过采用新颖的方式展示观点，让人耳目一新，听众全神贯注；还可以学会创造互动，让他人投入到谈话中，一次沟通就让人印象深刻等等。\u003cbr>\u003c/p>\u003cp>B2\u003c/p>\u003cp>在自我介绍中，说得好听很重要，能让人念念不忘才是重点。今天我们来一起探讨的片段，正是一个通过设计提问在短短的几分钟里让你的介绍在人群中脱颖而出，让人记忆深刻而与众不同。\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>接下来，请大家花点时间阅读我发到大家手上的原文片段，阅读完成的伙伴请举手示意我。现在开始阅读吧。\u003c/p>","ratings_count":1,"texts":[{"id":15058,"quote":"\u003cp>《凸法则》135-136\u003cbr>\u003cbr>她讲了2分钟，但我们中没有一个人听明白她是做什么的，况且她还是个总裁。想想错失机会便是痛失上百万美元的代价。当时在场的人都是成功的企业家，之后却没人记住她、提到她，或走过去和她谈合作。\u003cbr>\u003cbr>我问她:“你的工作对现实有什么影响，比如我们能看到的、闻到的、尝到的或者摸到的？”\u003cbr>她说：“我是经营医疗设备的，能够进行MRI（核磁共振成像）和CT扫描（电脑断层扫描）的设备。”\u003cbr>\u003cbr>“很好，这就跟现实生活搭边了，你在说的时候，我们能想到你谈论的东西的模样。不过不要就此打住，因为我们之间还没有建立真正的联系。你要把这种描述转化成3个问题：你做过MRI或CT扫描没？你有朋友做过MRI或CT扫描没？你有家人做过MRI或CT扫描没？”\u003cbr>\u003cbr>“提这3个问题有什么用？”\u003cbr>“如果你问一个人以前做过MRI或者CT扫描吗？他说没有，于是谈话便进入死胡同了。如果你同时提出这3个问题，那就大大增加了可能性，他们可能知道谁熟悉或使用过类似仪器。”\u003cbr>\u003cbr>想象一下，对方说：“有啊，我女踢足球时摔伤膝盖，曾经做过一次MRI。”这就和你从事的工作产生关联了，你可以接着说：“哦，我是经营MRI医疗设备的，就是像你女儿那样摔伤后曾使用过的仪器。”\u003cbr>“哦，是这样啊”，他们可能会这样说。相信我，一句感叹的‘哦，是这样啊’要比满腹疑惑的‘嗯，什么意思’好得多，更不用说一句无动于衷的‘哦’了。他们与你从事的工作有了联系，更有可能会记住你，而且如果他们需要MRI或者CT扫描的话，更有可能和你联系，因为人们都喜欢与自己认识和喜欢的人做生意。\u003c/p>","explains":"\u003cp>I【引导促进】\u003cbr>（what）今天这个片段给出的，是一个区别于大多数自我介绍的表达方法，这个方法通过提问互动，来达到双向沟通的效果，是一种能在短短几分钟的交谈中给人留下深刻记忆的互动式介绍法。\u003cbr>\u003cbr>文中是怎么给出这个方法的呢？\u003cbr>原文作者问这个做自我介绍的总裁：“你的工作对现实有什么影响，比如能看到、闻到、尝到或摸到的？”，这里提醒我们，介绍工作内容时，需要思考它的影响，包括可见可闻可触摸，也就是可体验到的具体影响。\u003cbr>做到这一步还不够，作者说“不要就此打住，因为还没有建立起联系”，所以需要把以上的描述转化成问题来提问，提问的目的有二：1.创造关联；2.避免对话进入死胡同。\u003cbr>由于把具体影响转化成问题提问，就会得到他人回应，最后顺着对方的回应，引入自己的工作内容。\u003cbr>\u003cbr>（how）【细化步骤】\u003c/p>\u003cp>此处做个提炼，具体的步骤包含这么三个：\u003cbr>一、思考具体影响\u003cbr>开口介绍自己之前，先思考你工作的具体内容（产品和服务）是什么？人们可以用它来做什么？最终能给人带来什么具体的影响或应用？\u003cbr>二、询问相关经历\u003cbr>其次，结合第一点，用2-3个问题询问对方及其身边人与你工作的关联，尽可能的覆盖他能回答的可能性。\u003cbr>三、引入具体内容\u003cbr>等对方回答后，再引入你的工作内容，也就是步骤一思考出来的具体影响或应用，告诉对方你就是做那个产品／服务的，可以带来什么影响或应用。\u003cbr>\u003cbr>（why）我们在介绍自己时，常用的方式是直接陈述身份、工作等内容的单向信息传递，其实是缺乏反馈的单向沟通的方式，表现为一方说，另一方被动的听和记忆。这种被动记忆由于大脑缺乏对信息主动形成关联，自然会将它们视为毫无特点的普通信息进行存储。它的坏处就是，我们很卖力的介绍，但过后对方还是把你忘了。\u003cbr>拆页的方法通过提问，让他人参与，形成有反馈的双向沟通，唤醒对方的经验和信息发生联系，触发主动记忆，大脑对产生了关联信息的重视程度更高，印象更深记忆更完整和牢固。因此，只是通过提问互动反馈，就让他人对你念念不忘。\u003cbr>\u003cbr>（举例）举个例子来说明一下，我目前承接了一块业务是微信SCRM系统，在介绍自己的工作时，使用以上的方法是这样的：\u003cbr>第一步思考具体影响\u003cbr>SCRM能做的是，在微信上进行〖客户关系、销售流程和销售人员的管理；它带来的具体影响是防止人员离职客户流失、建立和共享话术库缩短培训周期、提取标准话术一键解答客户疑问，并能大大提高成交率和缩短成交周期。〗\u003cbr>第二步询问相关经历\u003cbr>结合第一步的具体影响，问对方：“你公司／单位会不会关心人员离职客户流失的问题和怎样缩短销售周期？你朋友或你所知道的公司／单位会不会关心客户流失问题和怎样缩短销售周期？”\u003cbr>第三部引入具体内容\u003cbr>在对方回应了我们的问题后，告诉他们：“我做的是微信SCRM系统，就像你知道的那些注重销售的公司，这个管理软件可以用来防止客户流失、提高成交率和缩短成交周期。”\u003cbr>\u003cbr>（适用边界）这是个适用于现场能有或能创造询问对象和互动机会场合的自我介绍法，（总结）它通过提问创造了互动，区别于我说你听单向陈述的介绍方式，而是带有反馈的双向沟通，促进听众主动记忆，在短短几分钟内让人印象深刻。希望大家在每一次的介绍中，都能积累影响，让更多人记得你。\u003c/p>","interaction":"\u003cp>A3\u003c/p>\u003cp>\u003cbr>以上就是这个片段带来方法，接下来我们一起把知识转化为自己的能力，一起做个演练，请注意以下场景：\u003cbr>周末朋友约你喝茶，到场的多数是他圈子里的朋友，大家寒暄之后的，其中就有人问你“你是做什么的呀？”，你的朋友试图主动说明你的工作，但是说得不够清晰，你这时要怎么运用今天学到的方法来介绍自己，让对方印象深刻。\u003cbr>\u003cbr>【指令】\u003c/p>\u003cp>现在请大家以三人一组，一位扮演角色周末活动发起人小甲，邀请了朋友小乙和朋友小丙一起喝茶，小甲介绍小乙和小丙认识，小乙询问小丙“你是做什么工作的？”，角色小丙运用上面学到的方法回答这个问题介绍自己，接着出于礼貌反问小乙同样的问题，小乙同样用上今天学到的技能介绍自己。\u003cbr>\u003cbr>小组内各位自行认领角色小甲、小乙、小丙先组内讨论后演练3分钟，之后我们再邀请其中一组来现场展示，大家一起来听听他们是怎么对话的。现在开始。\u003c/p>\u003cp>拆书家：好了，大家讨论的很热烈，现在咱们邀请左手边这组伙伴来为大家做现场展示，有请。\u003c/p>\u003cp>【现场演练实录】\u003c/p>\u003cp>学习者小甲：“小乙，这是我朋友小丙。”\u003c/p>\u003cp>学习者小丙：“你好，小乙，我是小丙。”\u003c/p>\u003cp>学习者小乙：“你好，我是小乙，幸会幸会。小丙，你是做什么的呀？”\u003c/p>\u003cp>学习者小丙：“你有没有遇到过凌晨有事出门想买东西，周边却没有商店营业买不到东西的情况？你家人或朋友有没有也遇到凌晨想出来买东西却同样找不到商店的状况？”\u003c/p>\u003cp>学习者小乙：“还真有过，有时不得不跑出1-2公里去找商店。”\u003c/p>\u003cp>学习者小丙：“嗯，我从事的是无人自助售货机的业务，就如同你遇到的状况，我们通过铺设售货机给人们带来24小时无间断的售货服务。小乙，那你是做什么的呀？”\u003c/p>\u003cp>学习者小乙：“小丙，你过去出去旅游或想出去旅游，会不会通过旅行社、网络来制定你的出游计划？你身边的朋友有没有也在出游前尝试这些方式来制定计划？”\u003c/p>\u003cp>学习者小丙：“有的，我去年就和家人出去旅游了一趟，就是通过网络和旅行社来进行安排的。”\u003c/p>\u003cp>学习者小乙：“对的了，这方式很普遍了，我从事的是旅游酒店行业，我们结合线上线下采用真人客服服务，可根据客户具体需求私人定制，有温度有服务，让你真正体验旅游的愉快和放松。”\u003c/p>\u003cp>学习者小丙：“是吗，这太好了，认识你太荣幸了，下次有机会一定找你。”\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>感谢几位小伙伴的现场展示，为我们演示了今天这个互动式自我介绍法的具体运用，掌声送给他们。\u003c/p>\u003cp>这个方法因为有了互动，摆脱了冷冰冰的枯燥的自说自话，让彼此都参与其中。希望各位伙伴通过这个方法，在生活和工作中都能让人记得你。\u003c/p>\u003cp>今天我的分享就到这里，谢谢各位的陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1615469042000,"updated_at":1616399880000,"ria":true},{"id":9295,"topic":"拆书帮和RIA分享。","learn_goal":"从拆页中学习到如何运用1分钟开场白赢得关注","remark":"让学习者清楚了解拆书和拆书帮，并从拆页中学习到如何运用1分钟开场白赢得关注。","level":"TF1-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"陈念媛","city":"柳州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"自我介绍 ：\r\n大家好，我叫陈念媛，也可以叫我念媛。成年人的世界里每个人总有那么几个标签，我也有三个标签。我的第一个标签是，我是一个80后，一位3岁女孩的妈妈，在与孩子相处的过程中，更多的是与孩子一起学习共同成长。我的第二个标签，我是正面管教的家长讲师，希望在育儿路上给予孩子正面的管教。我的第三个标签是我正在做并且在努力的方向，成为三级拆书家，在拆书的路上获得大家的能量也给予大家更多的帮助。\r\n拆书帮介绍：\r\n那我们今天聚在这儿的目的是学习拆书帮的拆书法，我首先给初次听闻拆书帮的小伙伴简单介绍一下拆书和拆书帮。\r\n拆书的“拆”不是把书“拆散”，指的是转化和内化，它强调把图书的知识转化为学习者的能力。通俗的说，拆书是能够帮助你们在看完一本书之后有所收获，能够将书中的知识运用到生活中，提升自己各方面的能力。拆书法是可应用于个人学习的便签读书法，也可以是应用于组织学习的拆书帮现场学习法。\r\n那什么是拆书帮呢，拆书帮是基于拆书法的学习爱好者社群，它表现为各地的拆书帮分舵，是一个公益性的青年自组织，其使命是释放学习促进者的能量，帮助更多学习爱好者成长为拆书家。而我们今天的现场学习，既是让你们有所收获，也是我个人的一次学习力的提升。","ratings_count":1,"texts":[{"id":13075,"quote":"\u003cp>下面就是我们创造的开场白，不但帮助凯瑟琳赢得了认同和投资，而且帮她成为《商业周刊》2010年度最有前途的社会企业家之一。\u003c/p>\u003cp>你知道吗？现在每年接种疫苗有18亿。\u003c/p>\u003cp>你知道吗？接种那些疫苗时，有近乎一半使用重复利用的针头。\u003c/p>\u003cp>你知道吗？我们正在传播和延续我们试图预防的疾病。\u003c/p>\u003cp>想象一下，如果有一种针头是无痛的、一次性的，而且价格比当前的更便宜。\u003c/p>\u003cp>其实，你不用想象，我们已经创造出来了，这种针头就叫PharmaJet，正如这篇文章展示的这样……\u003c/p>\u003cp>接着她就朝着这个方向奔去了，你被调动起来了吗？和你一样，房间里的每个人也都被调动起来了。\u003c/p>\u003cp>让我们如实看待这个情况。PharmaJet团队过去这样开始他们的展示，解释他们是一个“皮下接种的医疗交付设备平台”。\u003c/p>\u003cp>哎呀！那样的介绍在一开场就失去吸引力了。可是，很多人都这样开始自己的交流，废话连篇的解释让观众简直无奈或只能轻叹一声。其实，观众这时已经得出“此问题难以理解”的结论了，于是转向更有趣或更紧急的事情。凯瑟琳有竞争优势，因为在1分钟里，她已经让所有人都感到好奇，渴望对主题有更多的了解。\u003c/p>","explains":"\u003cp>（what）\u003cstrong>通过阅读拆页我们了解到，\u003c/strong>1分钟开场白，成功吸引到了所有听众的注意力，对其内容产生好奇心，并赢得了认同和投资。\u003c/p>\u003cp>（why）如果你要成功推销你的产品，但给你的时间非常有限，你会如何吸引听众并且让他们了解你的产品，甚至能够成功交易呢？枯燥乏味的介绍可不能帮助你成功。用“你知道吗”的句式，提出问题吸引注意力，抓住消费者及听众的痛点，然后引出你的实施方案，这能让听众愿意继续听下去，最终接受你的建议。\u003c/p>\u003cp>（how）\u003cstrong>正确的做法是\u003c/strong>:\u003c/p>\u003cp>1.用“你知道吗？”的问句引起人们的好奇。\u003c/p>\u003cp>2.用“想象一下”的句式呈现人们期望的美好画面。\u003c/p>\u003cp>3.最后用“其实，我已经找到解决办法。”给出方法实现上面的美好画面。\u003c/p>\u003cp>（where）你们可以尝试用在与人沟通时介绍你的产品或者想法，希望得到他们认可的场景。\u003c/p>","interaction":"\u003cp>【A1】分享A1自己的过往经验\u003c/p>\u003cp>4月份的时候，我想通过领导听取意见日，跟领导提出我关于培训工作的一些建议和想法。\u003cbr>\u003c/p>\u003cp>领导说“现在已经快到下班时间了，所以你简要说明一下你的意见。”\u003c/p>\u003cp>我是这么开场的，我说“因为现在工作比较多，大家能够静下来学习的时间非常少，但学习是培养员工的途径，也是企业竞争力支撑，我看到有的企业运用xx方法进行培训效果很好……”\u003c/p>\u003cp>领导皱着眉打断了我，“我们公司已经有很多培训措施，谢谢你的建议。”\u003c/p>\u003cp>这次建言可以说是失败的。\u003c/p>\u003cp>（反思）回想当时我失败的原因有，我开场不够有吸引力，没有说出领导感兴趣的内容。\u003c/p>\u003cp>【A2】分享A2自己的未来应用\u003c/p>\u003cp>下一次在建言，（目标）我希望运用书中“你知道吗”的方法，与领导沟通，争取让领导接受我意见。\u003c/p>\u003cp>（行动）\u003c/p>\u003cp>1.xx领导你好，我是上一个月听取意见日提出新的培训方法的陈念媛。你知道吗，当时我的意见被您拒绝过。这并不是说您是一位不采纳员工的意见的领导，我自己反思后，是因为我没能清晰表达地结果。希望领导这次听听我的意见。\u003c/p>\u003cp>2.“想象一下，如果有一种培训方法，每年让员工的违章率降低30%，而且不需高价外聘培训师，是不是可以考虑一下？”\u003c/p>\u003cp>3.“其实，我已经找到了这个方法，这个方法叫做xx，这是我的实践数据请领导过目……”\u003c/p>\u003cp>结语：\u003c/p>\u003cp>如果这个片段的方法觉得对你有用，希望你用起来，用“你知道吗”的句式吸引别人的注意力。谢谢大家，今天我的分享到这。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1574154865000,"updated_at":1574154865000,"ria":true},{"id":8938,"topic":"拆书帮介绍和RIA分享","learn_goal":"让学习者清楚了解拆书和拆书帮，并从拆页中学习到如何运用1分钟","remark":"","level":"TF1-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"陈念媛","city":"柳州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"自我介绍 （\u003c1min）：大家好，我叫陈念媛，也可以叫我念媛。成年人的世界里每个人总有那么几个标签，我也有三个标签。我的第一个标签是，我是一个80后，一位3岁女孩的妈妈，在与孩子相处的过程中，更多的是与孩子一起学习共同成长。我的第二个标签是我的职业，我是一位电力工作者，为万家灯火奉献。我的第三个标签是我正在做并且在努力的方向，加入拆书帮，因为我喜欢这里的学习氛围，期望在拆书帮里自己的能力得到不断提升，最终成为三级拆书家。\r\n拆书帮介绍（\u003c2min）：现在大家对我有了初步的认识，那我们今天聚在这儿的目的是学习拆书帮的拆书法，我首先给初次听闻拆书帮的小伙伴简单介绍一下拆书和拆书帮，希望你们今天也有所收获。\r\n拆书的“拆”不是把书“拆散”，指的是转化和内化，它强调把图书的知识转化为学习者的能力。通俗的说，拆书是能够帮助你们在看完一本书之后有所收获，能够将书中的知识运用到生活中，提升自己各方面的能力。拆书法是可应用于个人学习的便签读书法，也可以是应用于组织学习的拆书帮现场学习法。而我们今天在这就是拆书帮的现场学习。\r\n那什么是拆书帮呢，拆书帮是基于拆书法的学习爱好者社群，它表现为各地的拆书帮分舵，是一个公益性的青年自组织，其使命是释放学习促进者的能量，帮助更多学习爱好者成长为拆书家，其愿景是帮助拆书家们升级学习力和促进他人学习的能力，影响身边的人。而我们今天的现场学习，既是让你们有所收获，也是我个人的一次学习力的提升，最终帮助我成为拆书家。","ratings_count":2,"texts":[{"id":12671,"quote":"\u003cp>【R】阅读原书拆页（&lt;2min）\u003c/p>\u003cp>下面就是我们创造的开场白，不但帮助凯瑟琳赢得了认同和投资，而且帮她成为《商业周刊》2010年度最有前途的社会企业家之一。\u003c/p>\u003cp>你知道吗？现在每年接种疫苗有18亿。\u003c/p>\u003cp>你知道吗？接种那些疫苗时，有近乎一半使用重复利用的针头。\u003c/p>\u003cp>你知道吗？我们正在传播和延续我们试图预防的疾病。\u003c/p>\u003cp>想象一下，如果有一种针头是无痛的、一次性的，而且价格比当前的更便宜。\u003c/p>\u003cp>其实，你不用想象，我们已经创造出来了，这种针头就叫PharmaJet，正如这篇文章展示的这样……\u003c/p>\u003cp>接着她就朝着这个方向奔去了，你被调动起来了吗？和你一样，房间里的每个人也都被调动起来了。\u003c/p>\u003cp>让我们如实看待这个情况。PharmaJet团队过去这样开始他们的展示，解释他们是一个“皮下接种的医疗交付设备平台”。\u003c/p>\u003cp>哎呀！那样的介绍在一开场就失去吸引力了。可是，很多人都这样开始自己的交流，废话连篇的解释让观众简直无奈或只能轻叹一声。其实，观众这时已经得出“此问题难以理解”的结论了，于是转向更有趣或更紧急的事情。凯瑟琳有竞争优势，因为在1分钟里，她已经让所有人都感到好奇，渴望对主题有更多的了解。\u003c/p>","explains":"\u003cp>（what）\u003cstrong>通过阅读拆页我们了解到，\u003c/strong>1分钟开场白，成功吸引到了所有听众的注意力，对其内容产生好奇心，并赢得了认同和投资。\u003c/p>\u003cp>（why）如果你要成功推销你的产品，但给你的时间非常有限，你会如何吸引听众并且让他们了解你的产品，甚至能够成功交易呢？枯燥乏味的介绍可不能帮助你成功。用“你知道吗”的句式，提出问题吸引注意力，抓住消费者及听众的痛点，然后引出你的实施方案，这能让听众愿意继续听下去，最终接受你的建议。\u003c/p>\u003cp>（how）\u003cstrong>正确的做法是\u003c/strong>:\u003c/p>\u003cp>1.用三个“你知道吗？”的问句引起人们的好奇。\u003c/p>\u003cp>2.用“想象一下”的句式呈现人们期望的美好画面。\u003c/p>\u003cp>3.最后用“其实，我已经找到解决办法。”引出解决方案。\u003c/p>\u003cp>（where）你们可以尝试用在与人沟通时介绍你的产品或者想法，希望得到他们认可的场景。\u003c/p>","interaction":"\u003cp>【A1】分享A1自己的过往经验（&lt;1min）\u003c/p>\u003cp>4月份的时候，我想通过领导听取意见日，跟领导提出我关于培训工作的一些建议和想法。\u003cbr>\u003c/p>\u003cp>领导说“现在已经快到下班时间了，所以你简要说明一下你的意见。”\u003c/p>\u003cp>这么一听，我一下就不知道从哪里开始说起了。\u003c/p>\u003cp>我说“因为现在工作比较多，大家能够静下来学习的时间非常少，但学习是培养员工的途径，也是企业竞争力支撑，所以我觉得加强培训很重要。我看到有的企业运用xx方法进行培训效果很好……”\u003c/p>\u003cp>领导虽然很耐心听完，但是最后还是把我打断了，说“你先把方案拟出来，在你们班组实施看看效果怎么样。”\u003c/p>\u003cp>这次建言可以说是失败的。\u003c/p>\u003cp>（反思）回想当时我失败的原因有2：1.我没有具体的实施方案，也没有去实施应用出成果，只停留在听到别人的方法好的阶段。2.说话也不够吸引力，导致领导觉得我啰嗦而打断我的发言。\u003c/p>\u003cp>【A2】分享A2自己的未来应用（&lt;5min）\u003c/p>\u003cp>（背景）前两天我老公说想去西藏旅游，确实是一个我们都没有去过的地方，但是我觉得太远，担心自己不适应高原反应，还怕晒黑。个人更想去滑雪，毕竟南方人对雪没有抵抗力。\u003cbr>\u003c/p>\u003cp>（目标）明天试图用书中“你知道吗”的方法，与老公沟通，争取今年春节后去神龙架滑雪。\u003c/p>\u003cp>（行动）\u003c/p>\u003cp>1.“老公，你知道吗？我大前年去玉龙雪山的时候，很多人都带着氧气瓶上山呢！我怕高原反应受不住。”\u003c/p>\u003cp>“你知道吗？我一直想去雪乡看雪呢，但新闻报道在雪乡吃不好住不好还乱收费。”\u003c/p>\u003cp>“你知道吗？我正在找一个适合的地方可以出去放松放松。”\u003c/p>\u003cp>2.“想象一下，如果有个地方，离柳州不太远，既不是高原，又不会有个高原反应，同时也能看到美丽的雪景，是不是可以考虑一下？”\u003c/p>\u003cp>3.“其实，我知道这个地方，就是去年表嫂去过的武汉神龙架，她说那里很美，高高的雪山，白白的雪，俯瞰山下，心情都开阔许多，而且冬天滑雪也好玩。我们要不要也去一次？”\u003c/p>\u003cp>结束：如果这个片段的方法触动到你，希望你用起来，谢谢大家，今天我的分享到这。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1569384093000,"updated_at":1569384093000,"ria":true},{"id":7296,"topic":"拆书帮和RIA分享","learn_goal":"让学习者清楚了解拆书和拆书帮，并从拆页中学习到如何运用1分钟","remark":"学习到如何运用1分钟开场白赢得关注","level":"TF1-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"陈念媛","city":"柳州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>大家好，我叫陈念媛，也可以叫我念媛。成年人的世界里每个人总有那么几个标签，我也有三个标签。我的第一个标签是，我是一个80后，一位3岁女孩的妈妈，在与孩子相处的过程中，更多的是与孩子一起学习共同成长。我的第二个标签是我的职业，我是一位电力工作者，为万家灯火奉献。我的第三个标签是我正在做并且在努力的方向，加入拆书帮，因为我喜欢这里的学习氛围，期望在拆书帮里自己的能力得到不断提升，最终成为三级拆书家。\u003c/p>\u003cp>现在大家对我有了初步的认识，那我们今天聚在这儿的目的是学习拆书帮的拆书法，我首先给初次听闻拆书帮的小伙伴简单介绍一下拆书和拆书帮，希望你们今天也有所收获。\u003c/p>\u003cp>拆书的“拆”不是把书“拆散”，指的是转化和内化，它强调把图书的知识转化为学习者的能力。通俗的说，拆书是能够帮助你们在看完一本书之后有所收获，能够将书中的知识运用到生活中，提升自己各方面的能力。拆书法是可应用于个人学习的便签读书法，也可以是应用于组织学习的拆书帮现场学习法。而我们今天在这就是拆书帮的现场学习。\u003c/p>\u003cp>那什么是拆书帮呢，拆书帮是基于拆书法的学习爱好者社群，它表现为各地的拆书帮分舵，是一个公益性的青年自组织，其使命是释放学习促进者的能量，帮助更多学习爱好者成长为拆书家，其愿景是帮助拆书家们升级学习力和促进他人学习的能力，影响身边的人。而我们今天的现场学习，既是让你们有所收获，也是我个人的一次学习力的提升，最终帮助我成为拆书家。\u003c/p>","ratings_count":2,"texts":[{"id":10731,"quote":"\u003cp>下面就是我们创造的开场白，不但帮助凯瑟琳赢得了认同和投资，而且帮她成为《商业周刊》2010年度最有前途的社会企业家之一。\u003c/p>\u003cp>你知道吗？现在每年接种疫苗有18亿。\u003c/p>\u003cp>你知道吗？接种那些疫苗时，有近乎一半使用重复利用的针头。\u003c/p>\u003cp>你知道吗？我们正在传播和延续我们试图预防的疾病。\u003c/p>\u003cp>想象一下，如果有一种针头是无痛的、一次性的，而且价格比当前的更便宜。\u003c/p>\u003cp>其实，你不用想象，我们已经创造出来了，这种针头就叫PharmaJet，正如这篇文章展示的这样……\u003c/p>\u003cp>接着她就朝着这个方向奔去了，你被调动起来了吗？和你一样，房间里的每个人也都被调动起来了。\u003c/p>\u003cp>让我们如实看待这个情况。PharmaJet团队过去这样开始他们的展示，解释他们是一个“皮下接种的医疗交付设备平台”。\u003c/p>\u003cp>哎呀！那样的介绍在一开场就失去吸引力了。可是，很多人都这样开始自己的交流，废话连篇的解释让观众简直无奈或只能轻叹一声。其实，观众这时已经得出“此问题难以理解”的结论了，于是转向更有趣或更紧急的事情。凯瑟琳有竞争优势，因为在1分钟里，她已经让所有人都感到好奇，渴望对主题有更多的了解。\u003c/p>","explains":"\u003cp>（what）通过阅读拆页我们了解到，1分钟开场白，成功吸引到了所有听众的注意力，对其内容产生好奇心，并赢得了认同和投资。\u003c/p>\u003cp>（why）如果你要成功推销你的产品，但给你的时间非常有限，你会如何吸引听众并且让他们了解你的产品，甚至能够成功交易呢？枯燥乏味的介绍可不能帮助你成功。用“你知道吗”的句式，提出问题吸引注意力，抓住消费者及听众的痛点，然后引出你的实施方案，这能让听众愿意继续听下去，最终接受你的建议。\u003c/p>\u003cp>（how）正确的做法是:\u003c/p>\u003cp>1.用三个“你知道吗？”的问句引起人们的好奇。\u003c/p>\u003cp>2.用“想象一下”的句式呈现人们期望的美好画面。\u003c/p>\u003cp>最后用“其实，我已经找到解决办法。”引出解决方案。\u003c/p>\u003cp>（where）你们可以尝试用在与人沟通时介绍你的产品或者想法，希望得到他们认可的场景。\u003c/p>","interaction":"\u003cp>A1：4月份的时候，我想通过领导听取意见日，跟领导提出我关于培训工作的一些建议和想法。\u003c/p>\u003cp>领导说“现在已经快到下班时间了，所以你简要说明一下你的意见。”\u003c/p>\u003cp>这么一听，我一下就不知道从哪里开始说起了。\u003c/p>\u003cp>我说“因为现在工作比较多，大家能够静下来学习的时间非常少，但学习是培养员工的途径，也是企业竞争力支撑，所以我觉得加强培训很重要。我看到有的企业运用xx方法进行培训效果很好……”\u003c/p>\u003cp>领导虽然很耐心听完，但是最后还是把我打断了，说“你先把方案拟出来，在你们班组实施看看效果怎么样。”\u003c/p>\u003cp>这次建言可以说是失败的。\u003c/p>\u003cp>（反思）回想当时我失败的原因有2：1.我没有具体的实施方案，也没有去实施应用出成果，只停留在听到别人的方法好的阶段。2.说话也不够吸引力，导致领导觉得我啰嗦而打断我的发言。\u003c/p>\u003cp>A2：（背景）前两天我老公说想去西藏旅游，确实是一个我们都没有去过的地方，但是我觉得太远，担心自己不适应高原反应，还怕晒黑。个人更想去滑雪，毕竟南方人对雪没有抵抗力。\u003cbr>\u003c/p>\u003cp>（目标）明天试图用书中“你知道吗”的方法，与老公沟通，争取今年春节后去神龙架滑雪。\u003c/p>\u003cp>（行动）\u003c/p>\u003cp>1.“老公，你知道吗？我大前年去玉龙雪山的时候，很多人都带着氧气瓶上山呢！我怕高原反应受不住。”\u003c/p>\u003cp>“你知道吗？我一直想去雪乡看雪呢，但新闻报道在雪乡吃不好住不好还乱收费。”\u003c/p>\u003cp>“你知道吗？我正在找一个适合的地方可以出去放松放松。”\u003c/p>\u003cp>“想象一下，如果有个地方，离柳州不太远，既不是高原，又不会有个高原反应，同时也能看到美丽的雪景，是不是可以考虑一下？”\u003c/p>\u003cp>3.“其实，我知道这个地方，就是去年表嫂去过的武汉神龙架，她说那里很美，高高的雪山，白白的雪，俯瞰山下，心情都开阔许多，而且冬天滑雪也好玩。我们要不要也去一次？”\u003c/p>\u003cp>如果这个片段的方法触动到你，希望你用起来，谢谢大家，今天我的分享到这。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1551507237000,"updated_at":1566964315000,"ria":true},{"id":7196,"topic":"如何设计一个引人注意的开场白","learn_goal":"学会如何设计一个引人注意的开场白，引发对方产生兴趣","remark":"","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"武小茉","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是陈茉，我的三个标签是爱阅读、爱学习和正在前进中的拆书家。\u003c/p>\u003cp>\u003cstrong>&lt;\u003c/strong>\u003cstrong>学习目标&gt;\u003c/strong>在跟随我完成本次现场学习后，学会设计一个开场，在开头就快速引起他人的注意。\u003c/p>\u003cp>\u003cstrong>&lt;FAB法介绍图书&gt;\u003c/strong>片段选自于《凸法则：从默默无闻到脱颖而出》，\u003cstrong>F（特征）：\u003c/strong>作者是[美]山姆•洪恩，美国心理学家，为美国联邦政府机构人员和世界顶级企业家、CEO开设专业的沟通心理课程。\u003cstrong>A（优势）：\u003c/strong>与市场上的沟通类书籍相比，这本书讲述了很多易懂的案例，让你学到立竿见影的招数。\u003cstrong>B（益处）：（B1）\u003c/strong>通过阅读这本书你可以学会高效表达自我，快速获得他人的好感。\u003cstrong>（B2）\u003c/strong>我们都知道一个好的开场对于演讲、产品介绍是多么的重要，通过今天的学习，你能够学会一种引人注意的开场方式。\u003c/p>","ratings_count":1,"texts":[{"id":10605,"quote":"\u003cp>下面就是我们创造的开场白，不但帮助凯瑟琳赢得了认同和投资，而且帮她成为《商业周刊》2010年度最有前途的社会企业家之一&nbsp;。\u003c/p>\u003cp>你知道吗？现在每年接种疫苗有18亿。\u003c/p>\u003cp>你知道吗？接种那些疫苗时，有近乎一半使用重复利用的针头。\u003c/p>\u003cp>你知道吗？我们正在传播和延续我们试图预防的疾病。\u003c/p>\u003cp>想象一下，如果有一种针头是无痛的、一次性的，而且价格比当前的更便宜。\u003c/p>\u003cp>其实，你不用想象，我们已经创造出来了，这种针头就叫PharmaJet，正如这篇文章展示的这样……&nbsp;&nbsp;\u003c/p>\u003cp>接着她就朝着这个方向奔去了，你被调动起来了吗？和你一样，房间里的每个人也都被调动起来了。\u003c/p>\u003cp>让我们如实看待这个情况。PharmaJet团队过去这样开始他们的展示，解释他们是一个“皮下接种的医疗交付设备平台”。\u003c/p>\u003cp>哎呀！那样的介绍在一开场就失去吸引力了。可是，很多人都这样开始自己的交流，废话连篇的解释让观众简直无奈或只能轻叹一声。其实，观众这时已经得出“此问题难以理解”的结论了，于是转向更有趣或更紧急的事情。凯瑟琳有竞争优势，因为在1分钟里，她已经让所有人都感到好奇，渴望对主题有更多的了解。\u003c/p>","explains":"\u003cp>\u003cstrong>&lt;\u003c/strong>\u003cstrong>意译案例&gt;\u003c/strong>\u003c/p>\u003cp>你知道吗？读书是这个世界上为数不多的投入最少、产出最多的事之一了。\u003c/p>\u003cp>你知道吗？没时间、没精力是许多成年人所面临的阅读问题。\u003c/p>\u003cp>你知道吗？读书没有用是因为你不知道怎么用，没有做到学以致用。\u003c/p>\u003cp>想象一下，如果有一种方式，能让你花费少量的时间、精力和几十元的费用，却收获几千元培训所获的的效果。\u003c/p>\u003cp>其实，你不必想象了，我们已经发现了，这就是RIA便签读书法，让你学以致用。\u003c/p>\u003cp>\u003cstrong>&lt;what&gt;\u003c/strong>在开场时以：【你知道吗？/你知道吗？/你知道吗？...想象一下，如果有... 其实，你不用想象，我们...】的句式相比原来的一开始就介绍更能吸引人的注意。\u003c/p>\u003cp>\u003cstrong>&lt;why&gt;\u003c/strong>首先这个方式相当于是一个逻辑上的自问自答，抛出问题，解答问题。先连用“3个你知道吗”的提问，引发大家的好奇，获取关注，想要继续了解；接着使用“想象一下”连接前3个提问内容，调动大家去想怎么解决，形成一种谁不想那样呢的场景；最后用“其实，你不必想象了，我们……”的句式过渡，引出要说的内容，对前面所提出的问题进行回答证实。\u003c/p>\u003cp>\u003cstrong>&lt;how&gt;\u003c/strong>具体要如何设计呢？\u003c/p>\u003cp>1、连续3个“你知道吗？”+要解决的问题或统计结果（可百度谷歌），为什么是3个呢，少于三个不足以引人注意和说服他人，多于3个会造成一种信息的干扰，反而是画蛇添足。\u003c/p>\u003cp>2、使用“想象一下，如果……”，针对第一步3个问题的回答，尽量用一句话总结。将对方带入一个场景，增加互动参与感。\u003c/p>\u003cp>3、“其实，你不用想象，我们……”回到要介绍的内容上，紧扣开头提出的问题。\u003c/p>\u003cp>\u003cstrong>&lt;适用边界&gt;\u003c/strong>如果是沟通的双方都知道的产品或内容就不需要使用这个方法了，更适用于推出新产品、演讲，推荐你认为值得的东西时。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;\u003c/strong>\u003cstrong>场景&gt;\u003c/strong> 小宇非常爱好学习英语，最近用了很不错的软件，想向朋友小牛推荐下，并且他也学了今天的开场方式，现在来做一个现场演练。没有语言环境、坚持不下去是学英语难的问题之一。“英语流利说”是一款融合创新口语教学理念和尖端语音评估技术的英语口语学习应用，让你“忍不住开口说英语”，帮你真正摆脱“哑巴英语”!中国有四分之一的人在学习英语，每年投入资金大约在300亿人民币，并且逐年递增。但实际效果依然不佳，在44个母语为非英语国家及地区中，英语熟练度仅排在29位。\u003c/p>\u003cp>\u003cstrong>&lt;\u003c/strong>\u003cstrong>整理实录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者演练：\u003c/strong>\u003c/p>\u003cp>洋洋扮演小宇，胡杨扮演小牛\u003c/p>\u003cp>小宇：小牛，好久不见了。\u003c/p>\u003cp>小牛：好久不见了呢！\u003c/p>\u003cp>小宇：你知道吗？我国有四分之一的人都在学习英语，每年投入的资金大约在300亿人民币，并且逐年在递增。\u003c/p>\u003cp>你知道吗？虽然投入了那么多的人力财力，实际效果却并不好，在44个母语为非英语的国家及地区中，英语熟练度仅排名第29位。\u003c/p>\u003cp>你知道吗？没有语言环境、坚持不下去时学英语难的问题之一。\u003c/p>\u003cp>想象一下，如果有一种神奇的方式或方法，能够让你忍不住开口说英语，帮你真正摆脱哑巴英语。\u003c/p>\u003cp>其实，你不用想象了，我们已经拥有了，这就是最近很火的流利说，让你摆脱哑巴英语。\u003c/p>\u003cp>小牛：听着是挺不错的，我也下载试试。\u003c/p>\u003cp>感谢小伙伴们的精彩演练！\u003c/p>\u003cp>&nbsp;\u003cstrong>&lt;总结&gt;\u003c/strong>我们都知道，好的开始是成功的一半，回顾一下今天的方法：运用连续3个“你知道吗？”+“想象一下，如果……”+“其实，你不必想象了，我们……”的句式做一个引人注意的开场。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1549171467000,"updated_at":1550214571000,"ria":true},{"id":6336,"topic":"一个句式帮助你快速吸引他人的注意力","learn_goal":"在学习这个片段后，学习者无论是开场还是介绍一件事时都能快速引","remark":"你有没有遇到过面试时被要求1分钟自我介绍，介绍完后面试官无动于衷？\r\n你有没有遇到过给上司或其他部门同事讲述你的新项目时，同事一脸茫然？\r\n你没有遇到过给客户介绍公司产品时，客户满不在乎？\r\n本书《凸法则》可以帮助你瞬间吸引听众的注意力。","level":"TF2-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"葫芦大王","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>\u003cstrong>【自我介绍】&nbsp;\u003c/strong>\u003c/p>\u003cp>大家好，我叫葫芦大王。今天我为大家拆解的书籍是《凸法则》中的片段。\r\n &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>在跟随我完成RIA现场学习后，大家无论是开场还是介绍一件事时都能快速引起听者得注意。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>分发原文片段\u003c/p>\u003cp>\u003cstrong>【F】\u003c/strong>:本书《凸法则》的作者叫山姆 洪恩。为美国联邦政府机构人员和世界顶级企业家、CEO开设专业的沟通心理课程。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>: 《凸法则》的精彩之处在于：本书不是说教如何成功，而是用极好的事例告诉读者，如何使参与活动的各方都能获益。书中有大量的实例和工具技巧总结，让你在瞬间引起他人的注意。\u003c/p>\u003cp>\u003cstrong>【B】\u003c/strong>: 你是否害怕过面试，向上级汇报工作，向顾客讲解新产品？并不是你缺乏勇气，而是没有找到最好的面对方式和技巧，担心被否定。神奇的“凸法则”将通过实用的技巧，带给你百倍的自信与勇气。本书分为8个章节，每个章节教你一种沟通技巧。\u003c/p>\u003cp>今天我们要来学习的是来自本书第1章节，在跟随我完成RIA现场学习后，大家无论是开场还是介绍一件事时都能快速引起听者得注意。\u003c/p>","ratings_count":1,"texts":[{"id":9630,"quote":"\u003cp>接下来是阅读原文片段，大家花1分种的时间阅读本片段，读完请举手示意下。\u003c/p>\u003cp>PharmaJet公司创始人凯瑟琳·卡伦德就是这种感觉，她对我说：“有好消息，也有坏消息。思林博德企业现在给我一个机会，让我进入一个纽约佩里中心满是投资者的房间。”\u003c/p>\u003cp>我告诉她：“这是个好消息呀。思林博德曾帮助热布卡公司女企业家罗宾·蔡斯筹资64亿美元之多。坏消息是什么？”\u003c/p>\u003cp>“我14: 30到场，只有10分钟的展示机会。只有10分钟，什么都展示不了，我怎么可能在10分钟之内就解释清楚我们的团队认证、临床实验和财务分析呢？”\u003c/p>\u003cp>“凯瑟琳，你没有10分钟，那些投资者已经听过其他16位的演讲了，你只有1分钟，你需要在1分钟内打破那个下午的夸夸其谈，吸引到他们的注意。”\u003c/p>\u003cp>下面就是我们创造的开场白，不但帮助 凯瑟琳赢得了认同和投资，而且帮她成为《商业周刊》2010年度最有前途的社会企业家之一。\u003c/p>\u003cp>你知道吗?现在每年接种疫苗有18亿。\u003c/p>\u003cp>你知道吗?接种那些疫苗时，有近乎一半使用重复利用的针头。\u003c/p>\u003cp>你知道吗?我们正在传播和延续我们试图预防的疾病。\u003c/p>\u003cp>想象一下，如果有一种针头是无痛的、一次性的，而且价格当前的更便宜。\u003c/p>\u003cp>其实，你不用想象，我们已经创造出来了,这种针头就叫PharmaJet，正如这篇文章展示的这样·····。\u003c/p>\u003cp>接着她就朝着这个方向奔去了，你被调动起来了吗？和你一样，房间里的每个人也都被调动起来了。\u003c/p>\u003cp>让我们如实看待这个情况。PharmaJet团队过去这样开始他们的展示，解释他们是一个“皮下接种的医疗交付设备平台”。\u003c/p>\u003cp>哎呀！那样的介绍在一开场就失去吸引力了。可是，很多人都这样开始自己的交流，废话连篇的解释让观众简直无奈或只能轻叹一声。其实，观众这时已经得出“此问题难以理解”的结论了，于是转向更有趣或更紧急的事情。凯瑟琳有竞争优势，因为在1分钟里，她已经让所有人都感到好奇，渴望对主题有更多的了解。\u003c/p>","explains":"\u003cp>好的，现在我们进行I部分的讲解\u003c/p>\u003cp>在开场前以：【你知道吗？/你是否？/你有没有？...想象一下，如果有... 其实，你不用想象，我们已经...】句式\u003c/p>\u003cp>开场，能够在瞬间吸引人的注意。\u003c/p>\u003cp>你有没有这样的经历，当你要介绍你的上司不知道或者不是很了解的事情，不知要如何介绍？\u003c/p>\u003cp>说了一大推，上司不知所云，丝毫不敢兴趣。\u003c/p>\u003cp>大家看文章中“你知道吗”出现了三次，它让大家既惊讶又好气，那么为什么这样用？文章最后说了连续3个设问句，让所有人都感到好奇，都极度好奇更多有关于主题得事。\u003c/p>\u003cp>那么我们具体该怎么做呢，我们看见原文中的开场白是：\u003c/p>\u003cp>首先用3个“你知道吗”的设问句引起听众好奇，紧接着用“想象一下”来链接解决方案，最后用“其实，你不必想象“告诉大家我们已经实现了。\u003c/p>\u003cp>所以，具体的步骤应该是：\u003c/p>\u003cp>第一步：【你知道吗？/你是否】提出3个关于这件事现存的问题或者困难，让听者产生惊讶或者好奇。\u003c/p>\u003cp>第二步：【想象一下，如果有】依次对第一步的3个问题描绘出解决了该问题的具体画面。让听众感同身受，要是这样就好了。\u003c/p>\u003cp>第三步：【其实，你不用想象，我们已经】最好告诉听众，其实我们已经解决了上面的问题，并有解决方案或者产品。\u003c/p>\u003cp>\u003cstrong>【举个例子】\u003c/strong>\u003c/p>\u003cp>【反面】就比如上周我作为我们组的培训联络员传达课程，我是这样告知我的同事的：\u003c/p>\u003cp>解决你日常沟通反反复复说不清！问题思考毫无头绪难突破！工作汇报杂乱无章没要点！\u003c/p>\u003cp>酷家乐职业素养系列课程第二讲《结构化思考与表达》，感兴趣的童鞋可以报名参加哦~报名链接：\u003ca href=\"https://www.wjx.top/jq/26584213.aspx\">https://www.wjx.top/jq/26584213.aspx\u003c/p>\u003cp>没一个小伙伴回复我，大家依然在忙自己的事，丝毫不关注我发的课程信息。\u003c/p>\u003cp>\u003cstrong>【正面】\u003c/strong>\u003c/p>\u003cp>本周我在告知课程的时候，利用【你知道吗？...想象一下，如果有... 其实，你不用想象，我们已经...】句式\u003c/p>\u003cp>第一步:【用”你知道吗/你是否/你有没有“引起听众的惊讶和好奇】\u003c/p>\u003cp>你是否在工作中觉得孤立无援，得不到同事帮助？\u003c/p>\u003cp>你是否觉得自己常常淹没在和同事沟通中，无法专心做事？\u003c/p>\u003cp>第二步：【用“想象一下”来链接解决方案，让听众思考】\u003c/p>\u003cp>想象一下，\u003c/p>\u003cp>如果有老师教你一种绝技：让合作伙伴为共同目标加班熬夜，不达目的誓不罢休；\u003c/p>\u003cp>想象一下，\u003c/p>\u003cp>如果有更好的沟通方法，快速的同步工作信息\u003c/p>\u003cp>第三步：【用”其实，不用想了，其实“告诉听众 我们已经实现这些想象了。\u003c/p>\u003cp>其实，不用想了，其实我们已经有这样的培训课了。本周大产品部&nbsp;&nbsp;【七宝】小姐姐为你解答疑惑，药到病除。\u003c/p>\u003cp>9月27日&nbsp;&nbsp;&nbsp;19点---20点30&nbsp;&nbsp;&nbsp;十楼培训教室&nbsp;《三个技巧轻松扫除团队合作障碍》开始报名了~~~\u003c/p>\u003cp>这样发出去后，本组同事在群里纷纷讨论，还真有2个小伙伴去参加讲座了。\u003c/p>\u003cp>\u003cstrong>【不这么做的坏处】\u003c/strong>\u003c/p>\u003cp>那么我来说一下不这么做的坏处。我相信大家都看到了，在没有用【你知道吗？...想象一下，如果有... 其实，你不用想象，我们已经...】句式前，直接抽象的讲解决了什么问题，大家对这样的话丝毫不赶兴趣，甚至都没人会去注意这段话。\u003c/p>\u003cp>但是在我【你知道吗？...想象一下，如果有... 其实，你不用想象，我们已经...】句式包装课程后，告诉听者以前有什么问题，解决了问题后是怎么样，最后告诉大家我们现在实现了。立马就引起了同事的注意和好奇。甚至最后引发了他们的行动。\u003c/p>\u003cp>&nbsp;当然也许有小伙伴会说，如何瞬间引起他人的注意，还有很多其他因素，诸如当时表达时的肢体语言等等，这些问题我们可以一一记录下来，课后详细讨论。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>这个方法适合在一场有高风险的场景大家想快速引起听者的注意力，比如面试时的自我介绍，向上司介绍你的新项目，给你的客户介绍你公司新研发的产品，相亲时想要博得对方好感。那么在和家人朋友闲聊时是，比如给老爸老妈介绍新鲜事物时，给朋友介绍一本你非常喜欢的书或者电视剧等没有高风险的场景下就不必要使用这种句式了，怎么开心怎么来。\u003c/p>","interaction":"\u003cp>设计家提问：\u003c/p>\u003cp>大家回想一下，也许是上周或者上个月，比如面试时的自我介绍，急迫的给朋友介绍一本你非常喜欢的书或者电视剧，向上司介绍你的新项目，给你的客户介绍你公司新研发的产品，相亲时想要博得对方好感，给老爸老妈介绍新鲜事物时等等类事得场景。或者其他场景中，你是如何开场或者介绍一个事情得。现在花2-3分钟时间小组内分享一下。\u003c/p>\u003cp>接下来，我们来请一个小伙伴分享一下他/她的故事\u003c/p>\u003cp>[学习者案列记录]\u003cbr>\u003c/p>\u003cp>以前我在面试的时候直接就介绍自己是谁，来自哪里，毕业于哪所大学，完全就是复述简历上的内容，和其他的面试者没什么区别，完全不能吸引面试官的注意力。\u003c/p>\u003cp>\u003cstrong>【A1+催化学习者应用】\u003c/strong>\u003cstrong>:\u003c/strong>\u003c/p>\u003cp>今天我们学了利用【你知道吗？...想象一下，如果有... 其实，你不用想象，我们已经...】句式快速引起听着得注意力，假如你再次遇到你刚刚分享得场景，利用【你知道吗？...想象一下，如果有... 其实，你不用想象，我们已经...】句式，你会怎么开场或者介绍一件事。\u003c/p>\u003cp>大家花2分钟时间在小组内分享。\u003c/p>\u003cp>稍后我们邀请一位小伙伴进行现场分享。\u003c/p>\u003cp>\u003cstrong>【学习者案列记录】\u003c/strong>\u003c/p>\u003cp>我以前帮一家猪饲料企业做商业计划书，\u003c/p>\u003cp>你知道吗？你的猪养起来为什么肥肉那么多呀？\u003c/p>\u003cp>你知道吗？你的猪为什么经常生病呀？\u003c/p>\u003cp>你知道吗？你的猪为什么产崽率这么低呀？\u003c/p>\u003cp>想象一下，假如有一种方式可以让你的猪崽生长特别快。\u003c/p>\u003cp>想象一下，假如有一种方式可以让你的猪崽生长的特别健康。\u003c/p>\u003cp>其实，你不用想象了，我们已经有和美国企业接轨的生物饲料。\u003c/p>\u003cp>我觉得用这样的句式去介绍会更好点。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":9631,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1540647023000,"updated_at":1540647213000,"ria":true},{"id":5685,"topic":"在演讲或介绍新观点时的开头牢牢吸引住听众的注意力","learn_goal":"TF3-2过级","remark":"","level":"TF2-4","duration":30,"status":30,"type":0,"chaishujia":{"username":"李小曼","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"各位伙伴大家好，我是拆书家李小曼。今天我带来的是《凸法则——从默默无闻到脱颖而出》，作者山姆•洪恩是美国权威心理学家，TED国际演说家。副标题清楚的告诉我们，这本书主要是帮我们快速增强自己在别人心中的影响力。","ratings_count":1,"texts":[{"id":8878,"quote":"\u003cp>我们今天拆解内容来自第十七章《创建现实关联》，在跟随我完成本次RIA现场学习以后，大家可以学会，在演讲或介绍新观点或传递某些理念的时候，通过提问-引用专业资讯这2个步骤，开头就牢牢吸引住听众的注意力。\u003c/p>\u003cp>为了便于大家讨论和分享，后面会安排小组讨论的环节，那现在我为大家分一下小组。\u003c/p>\u003cp>\u003cstrong>【事件场景】\u003c/strong>你是否遇到过，当你在公司的会议中发言时，大家是不是要么不听要么看手机？你是否和朋友聊天时，很羡慕那些侃侃而谈，却苦恼自己一开口就不吸引人呢？\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>你一定听说过关于演讲的七秒法则，它是说观众在开头能够让你发挥的时间只有七秒，那我们应该如何在这7秒抓住观众的注意力呢？你是否在谈话中争取人们的关注呢？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>其实无论是演讲还是沟通聊天，信息焦虑是我们现在的流行病，我们正同时遭受着急躁和信息碎片化的问题，我们可能无法获得别人的关注，无法与他们真正沟通。\u003c/p>\u003cp>\u003cstrong>【结果】\u003c/strong>不过，好消息是，这本书就是告诉你如何克服这些症状的,推荐给大家，本书介绍了一个让人“从默默无闻到脱颖而出”的法则：INTRIGUE法则，将这个单词拆开，就是这个法则的8个部分：开场白、新颖、高效、易记住、互动、给予、有用、实例。指导我们在这八个方面如何脱颖而出。\u003c/p>\u003cp>那么，请大家先来做个自测，看我们现在在谈话时的吸引力指数。给大家1分钟时间。 \u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>自测题\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>几乎总是（1）\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>经常（2）\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>偶尔（3）\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>很少（4）\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>几乎从不（5）\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1、我认为讲解任何东西，必须要从“是什么为什么”的概念开始讲。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、演讲的开头，我常常会从介绍自己的名字开始\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、我的谈话过程中说得最多的是“我”\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、我从不喜欢在谈话过程中引用数字\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、我从不在开头和观众做互动。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>总计\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>这个自测表测试的是你在谈话中争取人们的关注的程度，得分越高说明对方关注你的程度越高。\u003cbr>\u003c/p>\u003cp>\u003cstrong>1——9\u003c/strong>\u003cstrong>分以下\u003c/strong>，你比较感性，有时候会捉摸不定，情绪起伏很大，常常在和人沟通时，有一种断了线的感觉，想法没人听到。\u003c/p>\u003cp>\u003cstrong>10\u003c/strong>\u003cstrong>分-18分\u003c/strong>，你意识到沟通中有很多方法和技巧， 不再试图引起别人的关注，而是开始关注别人。\u003c/p>\u003cp>\u003cstrong>19\u003c/strong>\u003cstrong>分以上\u003c/strong>，恭喜你，你身边的人都认为你很会聊天，沟通不再是浪费时间的单向沟通，而是高效、双赢的双向沟通。\u003c/p>\u003cp>对照一下你手里的分数，那么你也许要问，如何提升，怎样改变呢？让我们回到书里，看看书向我们介绍什么样的方法。\u003c/p>\u003cp>\u003cstrong>【阅读原文R】\u003c/strong>\u003c/p>\u003cp>下面给大家3分钟时间，请阅读手中的拆页片段。\u003c/p>\u003cp>让人只是在理论上认同你还不够，必须得让他们在实际中运用你所说的。如果你分享的内容与他们的现实毫无关联，那他们为什么要关注呢？显然优先级还不足够引起他们的注意。\u003c/p>\u003cp>当我和Curemk公司的琼·法隆博士合作她的TEDx演讲时，我们都知道她的自闭症演讲主题不是影响少数人，而是影响全美国的绝大多数人。认识到这一点至关重要，所以琼一开始就说道：\u003c/p>\u003cp>在场的朋友们，有多少人认识患自闭症的人?请举手。\u003c/p>\u003cp>在场的朋友们，有多少人认识和患自闭症的孩子打交道的老师或治疗师?\u003c/p>\u003cp>在场的朋友们，有多少人了解当一个家庭有孩子患上自闭症时，这个家庭要遭受的心碎和困难?\u003c/p>\u003cp>哦，你们几乎所有人都举手了，我能想象出电视机前的朋友们也曾遇到过类似的情况。也曾遇到过类似的情况。\u003cbr>\u003c/p>\u003cp>自闭症患者数正在呈上升趋势。就在上个月，疾控中心做出估计，每68名儿童中就有一人被诊断为自闭施患者，而男孩子中每42人就有一人被诊断为自闭症患者。换个角度说，短短十年间，自闭定患者增加了近80%。这成了一种流行病，我们.…。\u003c/p>\u003cp>接着，法隆博士详细讲述了关于Curemak公司如何针对自闭症开发了一项治疗方案，这项治疗方案在临床试验中产生了非常可喜的成果，因此食品和药物管理局正在快速追踪它。\u003c/p>","explains":"\u003cp>\u003cstrong>提问一：\u003c/strong>原文拆页中，琼·法隆博士在TED演讲中的开场白只花了1分钟，就巧妙地把话题从抽象中剥离，使其变得和在场的每个人都息息相关。琼是怎样达到如此效果的呢?\u003c/p>\u003cp>（学习者回答：要求人们举手）\u003c/p>\u003cp>\u003cstrong>提问二：\u003c/strong>在这场TED演讲中的琼·法隆用提问的方式介绍“自闭症“，那么这3个问题是什么关系呢？\u003c/p>\u003cp>（学习者回答：层层递进的关系）\u003c/p>\u003cp>在这场TED演讲中，琼·法隆博士一上来就先阐明了与观众的关系。作家约翰·科特曾经说过“你知道首要什么吗？是紧迫感”。没错，演说的七秒法则中，是说观众在开头能够让你发挥的时间只有七秒，一定要出众，干净，利落和旗开得胜。\u003c/p>\u003cp>那么怎么做才是吸引注意力的好方法呢？在原文拆页中，我们可以看琼·法隆博士是这样做的：\u003c/p>\u003cp>\u003cstrong>首先，尽量以“你/你们”开头\u003c/strong>，大家最关心的是这次演讲到底和自己有什么关系。那就是“我为什么要注意你啊，对我有用吗？”\u003c/p>\u003cp>比如说：你正在着手准备做一场关于抑郁症的演讲，那么开场白可以这么说\u003c/p>\u003cp>“你们是不是认为抑郁症离自己很远？\u003c/p>\u003cp>“你们有没有人知道在中国，每15人个中，就有至少有1人患有抑郁症？”\u003c/p>\u003cp>和对方互动。要求人们举手。这个要求（真诚自然而非无缘无故地提出）使人从生理上参与进来，并且打造出一个画面，观众环顾四周，又看看自己，发现室内几乎所有人都举起了手。这个时候，他们举手、点头、回答的方式回应着你你，这就是好的沟通。\u003c/p>\u003cp>\u003cstrong>分享来源可靠的统计数据、惊人调查，让听众感到震惊，说明这一问题正在显著恶化，给人们一种紧迫感，激励他们现在开始关注和行动。\u003c/strong>\u003c/p>\u003cp>比如：据世界卫生组织的最新数据统计，全球有超过3亿抑郁症患者，其中，中国就有9000万患者。，到2020年抑郁症将成为将于癌症的人类第二大杀手”受和寻求治疗才是最理智的做法。\u003c/p>\u003cp>\u003cstrong>【异议处理】\u003c/strong>\u003c/p>\u003cp>你可能会问，难道演讲的开场白不应该是自我介绍吗？ \u003c/p>\u003cp>其实，我之前也有这个顾虑，直到我在另一本书《高效演讲》中找到答案。这本书指出，开场白必须有一个干净利落的开头，不说你的名字，不介绍自己，不寒暄，开门见山直接切中要害。\u003c/p>\u003cp>因为作者认为这样的开头太千篇一律，俗气无新意。如果确实要唠家常，介绍自己，说明演讲议程，那也要等到开场白介绍之后。\u003c/p>\u003cp>其实这个方法不只适用于公开场合讲话、演讲、沟通、分享，也适合和朋友聊天时于对话等很多场景。讲解产品、辅导下属，劝说他人、亲子教育、夫妻冲突等等也一样适合。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【细化步骤】\u003c/strong>总结一下，在开头就牢牢吸引住听众的注意力的过程可以分为3步\u003c/p>\u003cp>1、 \u003cstrong>提出问题，\u003c/strong>\u003cstrong>提出以“你们&quot;开头的问题呢，最好提问呈递增关系。\u003c/strong>谁困扰谁负责，我们借用“主语转换”这种语言暗示，可以引导听众。当使用“你们”开头时，人们不再是冷漠被动地听演讲，而是思考并和他们以前或现在发生的类似情况联系起来。\u003c/p>\u003cp>2、 \u003cstrong>和对方互动。\u003c/strong>要求人们举手。这个要求（真诚自然而非无缘无故地提出）使人从生理上参与进来，并且打造出一个画面，观众环顾四周，又看看自己，发现室内几乎所有人都举起了手。这个时候，他们举手、点头、回答的方式回应着你你，这就是好的沟通。\u003c/p>\u003cp>\u003cstrong>3、分享来源可靠的统计数据、惊人调查，让听众感到震惊，说明这一问题正在显著恶化，给人们一种紧迫感，激励他们现在开始关注和行动。\u003c/strong>给人们一种紧迫感，激励他们现在开始关注和行动。\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>为了让我们摆脱固有的沟通模式，我们还需要反复去练习。那下面我们来演练一下。\u003cbr>\u003c/p>\u003cp>让我们来假设一个场景,\u003c/p>\u003cp>在保险公司担任内训师的小明被老板安排在下周一的客户答谢会上介绍一款保险产品。小明听过你之前给他讲的，要在前几秒就抓住听众的注意力，不过他完成PPT方案之后，总觉得太过于枯燥，不够吸引人，所以来求助你。\u003c/p>\u003cp>小明的原方案\u003c/p>\u003cp>第一部分：开场。准备先礼貌的打招呼，问好，个人介绍（包括姓名、职务、工作年限、学历……）\u003c/p>\u003cp>第二部分：什么是保险？我国保险业务发展的规模和趋势，公司保险业务在行业内排名，要介绍款险种在全国销售等数据。\u003c/p>\u003cp>第三部分：这款险种的具体条款的解释\u003c/p>\u003cp>你正要开口跟小明分享对PPT方案的看法，突然，你想起了今天的拆书内容这3个步骤，，那么按照今天学习的拆书片段，你接下来要如何跟你的小明分享你的观点。我们分组进行讨论，5分钟后，每组推选1位小伙伴来说说你们组的讨论结果。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>陈陈：好开头的重要性上次我已经说过了，那再来看看，你的方案太过专业化。我今天看了本书，里面有个方法，你可以试试。\u003c/p>\u003cp>小明：太好了，怎么改呢？\u003c/p>\u003cp>陈陈： 开场做个人介绍，这个太普通了 ，你可以试试，先从“你们”开头，最好的递增关系提问，这样就可以让保险这个话题不再抽象，可以让你要介绍的险种变得和在场的每个人都息息相关\u003c/p>\u003cp>小明：那我试试“你身边有没有人得癌症？”“你知道癌症现在已经成为全球第一大杀手吗？”“你有没有想过如果自己或亲人得了癌症后如何解决昂贵的医疗费吗？”是这样吗，那然后呢？\u003c/p>\u003cp>陈陈：问得很好，然后就可以和观众进行互动了。\u003c/p>\u003cp>小明：那我准备让他们举手，或者站起来，或者邀请几位观众上台分享一下。\u003c/p>\u003cp>陈陈：没错，这样大家就会到这个话题对自己很有用，很有吸引力了。这时候你再举一些官方统计数据，说明癌症的逐年增加的比例，高昂的费用，或者最近上演的电影《我不是药神》也可以嘛，这样给人们一种紧迫感。\u003c/p>\u003cp>小明：这个数据公司都有，很详细的很有说明力的。\u003c/p>\u003cp>陈陈：那就行了，这时候你就可以很顺利的介绍险种的亮点，保障的权益等等。\u003c/p>\u003cp>小明：太好了，我就按这个步骤重新整理，相信肯定吸引人，现场促成很多大单呢。\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>好，刚才我们练习了提问-互动-引用专业资讯这3个步骤，达到吸引听众的注意力，达到增强你说话的影响力的目的。\u003c/p>\u003cp>我们生活和工作中，开口讲话的场景无处不在，相信你身边也有很多人和你一样希望一开口就吸引人，来提高自己的影响力吧。\u003c/p>\u003cp>那最后，给大家留一道家庭作业，请你把这个3个步骤分享给你身边的人，欢迎下周线下活动的时候，把你分享的经过复盘给我们。\u003c/p>\u003cp>好的，我今天的拆书分享就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1533284678000,"updated_at":1533284678000,"ria":true},{"id":5227,"topic":"用“襁褓”裹住谈话","learn_goal":"使用设定一个“限制”的方法，帮助自己节约时间成本，提高效率","remark":"","level":"TF2-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"师麦","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>大家好，我是师师，今天给大家带来的这本书书是《凸法则》。\u003c/p>\u003cp>F：本书作者山姆•洪恩是一位心理学家，风靡全球的沟通学作家。通过精彩的开场，创新的思路，高效的沟通等方面，帮助我们更好地表现出自己的优点，赢得别人的关注。\u003c/p>\u003cp>A：相较于别的社交类书籍，“凸法则”是一种运用心理学，达到“知己知彼”状态的竞争法则，本书还结合了大量的案例，提供了可使用的场景。\u003c/p>\u003cp>B：当我们相互竞争时，可以通过展示罕见特点为自己加分；当我们面对紧张气氛而又想不出缓解的方法时，不妨关注并记录令你哈哈大笑的事物，再根据主题灵活应用。\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>通过这次RIA学习， 学习者在需要简练说话时，可以通过设定一个“限制”的方法，节约时间成本。\u003c/p>","ratings_count":1,"texts":[{"id":8342,"quote":"\u003cp>P110\u003c/p>\u003cp>用“襁褓”裹住谈话\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;午餐时，里克和我进行了一次有趣的对话，他承诺一定做到“说话简练”。他说：“我们的讨论对我的影响很大。如果我总是漫无目的地说，那我的谈话就一点儿范围也没有，我的沟通就是开放式的，我需要‘用襁褓裹住它’。设定适当的截止时间和更严格的范围限制，可以让我每个字都说到点子上。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 举个例子，如果我确定一共写10页纸，这就是一件‘稳定背心’，会改变我写作时的心态。问题不再是“这个例子或见解能引人注目吗？”而是变成了“我是不是超出了10页纸的限制？如果超出了，肯定有些没用的内容要删除。”\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;好，小伙伴们都读完片段了，下面我来进行I部分的讲解。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 给要做的事情加上一些限制，可以让我们把事情做得更有效率。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 比如说：在每周晨会上，明明只要告诉大家，接下来这周需要完成哪些事情，但是在表述的过程中，因为没有时间的限制，就会发生越说越多的情况，并且通常情况下，这些多的部分对晨会没有多大帮助，反而会消耗多余的时间。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 那么，我们可以怎么做来帮助自己做事情更有效率。大家可以试试按照下面几个步骤：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>确定内容\u003c/strong>；就像文章中里克说的：“如果我总是漫无目的地说，那我的谈话就一点范围也没有”，这里其实就是告诉我们，谈话开始之前，我们需要明确主题，具体要做什么。怕自己会忘记，或者是一开始没这方面习惯的小伙伴，可以用本子记录自己要做的事情，在谈话的时候，就可以按照本子上记录的来说明。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>给个限制\u003c/strong>；这就是原文所说的“稳定背心”，也就是原文中的“设定适当的截止时间和更严格的范围限制”。对要做的内容给定一个限制，可以是时间（各类会议谈话），也可以是内容长度（发邮件时） 。这里特别说明一下，限制的给定，是从我们已经做过的事情里总结出来的，比如说晨会，大概在开过4-5次之后，我们得出，每次每人花个3分钟的时间足够了。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>修改内容\u003c/strong>；对比1，2的差距，当发现内容超过限制时，修改内容。不断比较修改，直到内容符合限制。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;\u003cstrong>举个例子\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 【反面】我们小组之前每个周一会有10-15分钟的时间讨论上周工作进度以及这周工作内容，但是经常会遇到明明内容很少并且只有3个人的讨论（这个3分钟是我们经过4-5次讨论得出的），却要花上半个小时的时间。\u003c/p>\u003cp>【正面】现在每周一早上我们是这么做的。首先，先在手机上记下自己要讲述的几件事情；然后限制自己在3分钟内讲完工作进度和工作内容；接着对比记录的事情和限制，看看会不会超出时间限制，讲述的内容是不是存在没用的内容。不断修改内容，符合限制。同时，我也要求小组成员也这么操作，按照1，2，3这三步来准备汇报情况，提高一整个讨论进度。\u003c/p>\u003cp>\u003cstrong>(\u003c/strong>\u003cstrong>不这么做的坏处)\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 那么，我来说一下不这么做的坏处。不难看出，在晨间例会的时候， 我们小组不仅没把事情说清楚，还花费了大量的时间。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 但是当我们给晨间例会加上了时间的限制之后，不但减少了会议时间，还让大家清楚的知道工作进度。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 当然有的小伙伴会想，如果我在讲“废话”的同时解决了别的问题，也算是提高效率。这里需要明确的是，我们是针对自己当下正在做的事情提高效率，对于延展话题的想法，可以先记录下来，结束了之后在讨论。\u003c/p>\u003cp>\u003cstrong>(\u003c/strong>\u003cstrong>适用边界)\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;这个方法，比较适合用在我们需要限定时长／内容的事情，比如说开会，写演讲稿，这样做不仅可以提高效率，还能锻炼自己的说话能力，写作能力。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;但是当我们和亲戚朋友交流自己最近发生的一些琐事的时候，就不要有那么多限制了，怎么欢快怎么来。\u003c/p>","interaction":"\u003cp>【A1】\u003cbr>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>大家试着回想一下，可能是在上周，也可能是在上个月，当你在开会的时候（任何职业），或者是你在做销售方案的时候（销售），再或者是给领导发邮件的时候，也可能是其他的情况下。有没有遇到过因为没有限制，让谈话，方案描述，邮件内容多出了很多没用的内容，现在大家用1分钟的时间回想一下，并记录在便签上。\u003c/p>\u003cp>（确认1分钟时间）好的，大家现在花2-3分钟时间小组内分享一下。\u003c/p>\u003cp>下面，我们来请一个小伙伴分享一下他/她的故事。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>现场小伙伴分享，家里孩子放学回家之后，会监督孩子写作业。本来25分钟左右就能完成的作业（按照平时还自己写作业的时间）。但是因为在开始写作业的时候会问孩子，今天语文有什么作业，数学有什么作业，这里就要占用15分钟的时间， 让写作业的时间变长。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>好，如果现在我们坐着时光机，到达我们刚才自己回忆起的场景下，如果重新来一次，使用今天学习的方法，你会怎么做呢？大家花1分钟的时间，把解决办法写在便签上。\u003c/p>\u003cp>（确认1分钟时间）好的，大家现在花2-3分钟小组内和小伙伴分享一下。\u003cbr>\u003c/p>\u003cp>下面，请刚才分享的小伙伴来对自己的故事进行一下改造，如果回到当时发生的场景，他/她会怎么做。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习了今天这个技能之后，我对小孩放学回家写作业可以通过以下三步，帮助自己在限定的时间内监督孩子写完作业\u003c/p>\u003cp>1.&nbsp; 明确目标；明确自己要做的事情是监督孩子写作业。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp; 加个限制；给监督孩子写作业的时间加个限制，按照之前几次的经验得出，大概需要25分钟时间，孩子可以完成数学作业。这是监督的时间。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp; 修改内容；在这个过程中，避免自己做和目标无关的事情，比如之前的问孩子今天都有些什么作业，因为孩子自己知道都有什么作业，只要做就可以了。同时总结时间经验，在之后的作业中也可以不断完善【时间限制】\u003c/p>\u003cp>通过以上三步，我不仅用时间这个“襁褓”裹住了监督孩子写作业这件事情，节约了自己的时间，还提高了孩子写作业的效率，让孩子在这个时间段内，专心完成作业。\u003c/p>\u003cp>今天，我们学习了用“襁褓裹住谈话”，现在我们来复习一下。当我们要做一件事情是，首先要确定内容，明确我们要做什么事情；接着加个限制，给要做的事情加上一个限制，可以是时间上的，也可以是内容上的，还可以是其他别的限制；最后修改内容，对照1，2之间的差距，不断修改完善要做的事情。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1527692674000,"updated_at":1530021171000,"ria":true},{"id":4525,"topic":"如何与陌生人打开话题","learn_goal":"学会用四个方法和陌生人开展一场有意义的对话","remark":"","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"孙晶晶","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"大家好，我是一级拆书家晶晶，我今天带来的这本书叫做《凸法则》。 非常感谢各位小伙伴、拆书家还有观察家抽出时间来到这里，一起分享交流、互相学习，因为有大家的到场和支持陪伴见证彼此的成长过程，在拆书的道路上我觉得很愉快也很踏实。\r\n今天的现场学习后，你能够与陌生人聊天中不再尬聊，而是问开放式的问题去寻求对方意见、使用“跟我讲讲”的魔法词语，开始一场有意义的对话。\r\nB:\r\n你是否曾有过怀才不遇、一腔抱负，难以实现的痛苦？\r\n你是否正为被面试官拒绝、客户拒绝、竞争失利而感到困扰？\r\n这本书帮你永远告别被拒绝后的苦恼、只当配角的平凡、怀才不遇的郁愤。让你高效展现自我，助你实现人生价值。\r\nF:这本《凸法则》作者是山姆•洪恩（Sam Horn），美国心理学家，为美国联邦政府机构人员和世界企业家、CEO开设专业的沟通心理课程。将带你用8步成功逆袭，征服所有你想征服的人。\r\nA:这本书是社会科学类的图书，看这本书就好像在和作才对话，10秒钟就会被深深吸引了。集实用、鼓舞人心、切实可行于一体。","ratings_count":1,"texts":[{"id":7541,"quote":"\u003cp>和陌生人，开始有意义的对话&nbsp; 《凸法则》P143\u003c/p>\u003cp>如何摆脱陈词滥调(没人对这些感兴趣)，和陌生人开始有意义的对话和沟通。\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 别在开始就问那些老掉牙的问题。\u003c/p>\u003cp>无聊的问题总有无聊的答案。试试“你激动万分的工作进行得怎么样啦？”或“你周末一般做什么啊？\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 寻求意见。\u003c/p>\u003cp>杂志创始人马尔克姆·福布斯说：“要抓住男人的心，首先要抓住他们的意见。”抓住任何人的心都是要通过抓住他们的意见。问一句“你有什么意见吗？”就相当于发送了一条信息，即你认为他有智慧可以分享，而且你十分欢迎他的分享。没了填鸭式的陈词滥调，你正走向富有成效的交流之路。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 使用“跟我讲讲”这个魔法词语。\u003c/p>\u003cp>很多人在一开始谈话的时候问封闭式问题，结果对方一个词语就可以结束对话了。比如：“你喜欢这次商会会议吗？”对方回答：“喜欢。\u003c/p>\u003cp>”跟我讲讲”这个魔法词语会把蜻蜓点水式的交流变成更深刻、更有意义的对话，让你们真正了解一个人。比如：“我错过了这次商会会议，你能跟我讲讲都谈了哪些内容吗？”\u003c/p>\u003cp>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 折回谈话\u003c/p>\u003cp>每次他人说完之后，你都面临一个选择。你可以接着说我”也可以说“你…吗？”折回谈话。如果每次别人说完之后你就开始谈论自己，别人就会丧失继续谈话的兴趣\u003c/p>\u003cp>比如你问：“现在的商会主席是谁啊？”\u003c/p>\u003cp>对方回答：“朱迪·格雷。”\u003c/p>\u003cp>你接着说：“哦，我知道朱迪，她就住在我们小区，我记得有一次\u003c/p>\u003cp>唉。以“我”开头的句子让注意力都集中在我们值的感觉和观点、我们所知道的和所做过的事情上。如果你接着抛出一个以“你”开头的问题，那情况就大有不同了。感受一下，如果你得到回答后接着说：“哦，现在的主席是朱迪啊，你知道她今年的商会目标是什么吗？”\u003c/p>\u003cp>“你”开头的问题让注意力都集中在对方身上。人们能够感受到你的真诚，你是真正想要了解他们的，因为你确实是如此。\u003c/p>","explains":"\u003cp>如何结束和陌生人的尬聊，开始一场有意义的对话呢？我们可以从这4个方面做：\u003c/p>\u003cp>1：在开始时，简单客套后，问一些开放式的问题（例如：周末都做些什么？工作进行得怎么样？）；\u003c/p>\u003cp>2：针对话题寻问对方的意见；\u003c/p>\u003cp>3：接着使用魔法词语“跟我讲讲”，把话题引入更深；\u003c/p>\u003cp>4：抛出“你”字开头的问题，折回谈话。让聊天持续。\u003c/p>\u003cp>适用边界：上面的步骤可以帮助我们和陌生人沟通。）\u003c/p>\u003cp>预防异议：\u003c/p>\u003cp>或许有人会不喜欢这个技巧，因为感觉它们太不自然了。这些技巧并不是僵硬的公式，也不是要操纵别人。它们更不是隐瞒鬼计，而是基于诚意之上的工具，可以帮你达成真正与人沟通。当然能够很自然地与人会面当然是很棒，但现实是我们大多数人不善于此，而是觉得尴尬。\u003c/p>\u003cp>这4步的方法可以帮你获得技巧，开始有趣的聊天。既然是一种技巧，就像弹钢琴需要技巧一样。在你初学弹钢琴时，通常先开始练习音阶，练习一定程度后，你的手指对琴键熟练后，根本就不用想手指放在哪里也能弹出动听的音乐。\u003c/p>\u003cp>学习聊天的音乐也是如此，一旦你学会了这些，你可以甚至不用再想它们了，因为它们成了你的一部分。\u003c/p>\u003cp>&nbsp;&nbsp;例子：一个刚毕业的大学生，他用亲身经历验证了这个技巧的力量。他在一个陌生的城市待了半年都过得很不好，他认为那个地方很不友好，尽管他去泡各种场子结识人，也没认识到什么朋友。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; 后来他学到这个技巧，一次见到陌生同龄人打过招呼，他决定试着问对方周末一般都想去做什么？结果对方就开始跟他说很多，他接着问对方这些活动一般都和哪些人一起做呢？他又会用“跟我讲一讲最近参加的有趣的活动”让对方说更多的细节，最后，他试着询问对方如果一群共同爱好的人经常一块活动，你感觉怎么样？\u003c/p>\u003cp>&nbsp; &nbsp; 就是这样子，后来他有一个很大的朋友圈子，大家在一起总有有趣的事要做。他再也不觉得这个城市不友好了。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2(分步催化1)\u003c/strong>请各位小伙伴想一想，你在接下来的一到二周内会遇到以下哪种情况呢？ \u003c/p>\u003cp>比如：参加一个陌生的社群活动、面见一份新工作的领导、到一个新公司上班、会见到你慕名已久的大咖？这个场景会在什么时候，什么地方呈现呢？。在小组内和小伙伴们讨论，3分钟后每组邀请一个代表回到大组里分享。\u003c/p>\u003cp>强调：每小组内只需要讨论出一个具体的场景就可以了。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>逢生：下周会到一个新公司工作，见到新同事。\u003c/p>\u003cp>天后：下周末下午年会上会遇到做埃里克森培训的。\u003c/p>\u003cp>\u003cstrong>A2(分步催化2)：\u003c/strong>刚刚每个小组都讨论了可以使用这个方法的场景事件。\u003cstrong>当你遇到那个场景的时候，你突然想到了今天学到的，\u003c/strong>并且想试一试你将如何和对方开始有趣的聊天呢？先在小组里和小伙伴讨论，3分钟后每组邀请一个代表回到大组里分享。\u003c/p>\u003cp>学习者案例：\u003c/p>\u003cp>\u003cstrong>一、逢生：\u003c/strong>下周会到一个新公司工作，见到新同事。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;1、在小组同事互相介绍后，找搭档同事聊聊，用开放式问题“咱们现在这个项目进展是什么样的情况呢？”向同事了解更多；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;2、接着问问同事“现在咱们这个项目里的软件部分到哪一步了呢？”；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;3、再问“跟我讲讲关于软件部分我们团队下一步的方向呗”；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;4、最后问&quot;你觉得我应该在哪些方面着手去做，对目前团队的工作更有促进？”\u003c/p>\u003cp>\u003cstrong>二、天后：\u003c/strong>下周末下午年会上会遇到慕名已久做埃里克森培训的A。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;1、 和A打招呼后，用开放式问题“你做的埃里克森培训怎么样？”打开话题；\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2、接着问“它主要适合哪些人去学习呢？”；\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 3、“跟我讲讲，这个课程会学到哪些模块呗？”：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 4、“你觉得一个想入培训的新手小白学这个，怎么样？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1516315883000,"updated_at":1516315883000,"ria":true},{"id":3211,"topic":"学会抓住“你的职业是什么”展开对话","learn_goal":"凸法则","remark":"在如今这个信息爆炸，耐心有限的快节奏时代，与他人建立“连接”时，如何瞬间引起别人的深度注意并获得认可，是种必不可少的能力。\r\n参加商务活动、与旧友聚会、或者相亲等现场，我们经常被问“你的职业是什么”。周日来123茶楼，一起学习如何利用这个问题让自己与对方建立联系","level":"TF2-3","duration":20,"status":0,"type":0,"chaishujia":{"username":"甜橙大王","city":"杭州"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"大家好，我是甜橙大王；一个爱吃橙子外号橙子的天秤妹子。目前负责一家互联网企业的人力资源管理工作。我好奇一切值得好奇的事物，未来要成为一名有个性的三级拆书家。\r\n作为刚毕业的学生，初入职场如何从万千学生中获得面试官的青睐？作为众多单身者中的一枚，在各式相亲现场又如何可以快速撩动对方。古语有云“有道无术，术尚可求；有术无道，止于术”。本书能在沟通，表现力方面让精英的你如虎添翼，也可以帮助初出茅庐你给未来的生活和目标做坚实并行之有效的铺垫。\r\n作者山姆·洪恩是美国联邦政府沟通技巧内训课超级讲师、成功指导企业家获得数亿美元投资的高端王牌沟通策略师。是美国心理学家，国际演说家，沟通策略师。\r\n它倡导的的沟通精神是：真实、直接、全新、有效、互动，且极具可操作性，还用了很多易懂的案例来讲述。且凸法则是美联邦政府的沟通技巧内训课。给此书背书的不仅仅有知名企业家，还有白宫研究人员，著名ted演讲者，奥巴马竞选团队首席运营官等。\r\n《凸法则》适合想在与人沟通、建立连接却无从下手的人阅读学习。\r\n今天我为大家带拆片段的主题是：如何借用“你的职业是什么”来切入彼此关系的连接","ratings_count":0,"texts":[{"id":6045,"quote":"\u003cp>\u003cstrong>[学习目标]\u003c/strong>\u003c/p>\u003cp>通过该片段ria的学习，想与陌生人快速建立联系时可以使用该片段技能，让彼此快速找到共同话题，从而摆脱冷场尴尬。\u003cbr>\u003c/p>\u003cp>\u003cstrong>[原文]\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>无论我们去哪儿，喜欢与否，人们见面总会问道：“你从事什么工作？”我们要明白，他们这么问，并非真的想了解我们的工作内容，而是想知道我们之间有什么共同点，能否进行有意思的对话。\u003cbr>所以从现在开始，不要再做“电梯演讲”了。你见过谁喜欢听电梯演讲吗？电梯演讲是一场有观众在场的独白，而不是能够有效沟通的对话。\u003cbr>这对在INC500/5000会议上参加我的《流行起来！为一切打造完美姿态、书名和标语》研讨会的参与者来说，是一个真正 &nbsp; 的顿悟。我们当时对电梯演讲进行了头脑风暴，我问年度杰出 企业家科琳：“你是做什么的？”\u003cbr>&nbsp;她讲了2分钟，但我们中没有一个人听明白她是做什么的，况且她还是个总裁。想想错失机会便是痛失上百万美元的代价。当时在场的人都是成功的企业家，之后却没人记住她、提到她，或走过去和她谈合作。\u003cbr>我问她：“你的工作对现实有什么影响，比如我们能看到的、闻到的、尝到的或者摸到的？”\u003cbr>&nbsp;她说：“我是经营医疗设备的，能够进行MRI(核磁共振成像）和CT扫描（电脑断层扫描）的设备。”\u003cbr>&nbsp;“很好，这就跟现实生活搭边了，你在说的时候，我们能想到你谈论的东西的模样。不过不要就此打住，因为我们之间还没有建立真正的联系。你要把这种描述转化成3个问题：你做过MRI或CT扫描没？你有朋友做过MRI或CT扫描没？你有家人做过MRI或CT扫描没？”\u003cbr>“提这3个问题有什么用？”\u003cbr>“如果你问一个人‘以前做过MRI或者CT扫描吗？’他说没有，于是谈话便进入死胡同了。如果你同时提出这3个问题，那就大大增加了可能性，他们可能知道谁熟悉或使用过类似仪器。”\u003cbr>想象一下，对方说：“有啊，我女儿踢足球时摔伤膝盖，曾经做过一次MRI。”这就和你从事的工作产生关联了，你可以接着说：“哦，我是经营MRI医疗设备的，就是像你女儿那样摔伤后曾使用过的仪器。”\u003cbr>&nbsp;“哦，是这样啊”，他们可能会这样说。相信我，一句感叹的‘哦，是这样啊’要比满腹疑惑的‘嗯，什么意思’好得多，更不用说一句无动于衷的‘哦’了。他们与你从事的工作有了联系，更有可能会记住你，而且如果他们需要MRI或者CT扫描的话，更有可能和你联系，因为人们都喜欢与自己认识和喜欢的人做生意。\u003cbr> &nbsp; \u003cbr> &nbsp;\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>我们经常在各种场合被他人问到，“你是从事什么职业的呀？”“你是干什么的呀？”我们往往会用很专业的词汇去做说明，虽然我们有时候知道自己的职业很冷僻，可是对方这样问了我们得回答呀。其实，很多时候我们会问对方这个职业，是希望找到彼此之间可能存在的关联。\u003cp>那么怎么使用片段中这个方式呢（具体步骤）\u003c/p>\u003cstrong>先把自己的职业、行业具像化\u003c/strong>，比如写代码的最终形成的产品是什么，比如是生产零件的，一般它会变成什么产品的配件，而这个产品是生活中常见的。这样就会有亲切感，容易产生很多联想。\u003cbr>我平时是一个农副电商的运营顾问，我为这个岗位的具象是平日里各种电商大促的幕后“黑手”\u003cbr>\u003cstrong>接着把这个产品更加的生活化\u003c/strong>，将它放到我们日常生活会接触的场景中，\u003cbr>\u003cp>比如运营就是从电商促销活动，递进到给小朋友买日用品，到为家人准备生鲜蔬菜，把几个不同的场景例给对方。来增加不同年龄、人群都会产生联系的可能性。\u003c/p>\u003cp>最后你要记住它们。\u003c/p>具体怎么用呢，比如我前几天跟几个朋友一起吃饭，有个制造企业的朋友问我，你是做什么的呀？ \u003cbr>于是我这样说：刚过的618你剁手没，双十一，双十二你们都会买什么品类的产品呀，最近亚马逊有很多会员活动蛮好的你有没有给小朋友买书呀，有没有试过在网上订购过放心蔬菜水果呀？\u003cbr>她说有呀有呀，我是马云身后的败家娘们。\u003cbr>我说，我就是帮助老板的团队设计活动吸引你们去网站上花钱，做各种活动的。\u003cbr>接着她就开始和我说网购，吐槽一些活动，还给我推荐来一些店铺。\u003cbr>\u003cp>这个对话中，最初妹子可能觉得与在坐的我比较陌生，想打破僵局。我也巧用了这个片段的对话技巧，激发了她和我更多聊天的欲望。。\u003c/p>当你遇到被这样问时就可以用起来了。帮助你缓解氛围，让彼此可以找到更多接下去的话题。\u003cbr>当然你也可以反向使用该办法，在问对方这个问题时不断的追问他与岗位、行业等相关的生活场景来引出彼此更多的话题。\u003cbr>\u003cp>&nbsp;这个方法适合用来打破初次交谈的僵局，使彼此陌生的两个人一下子可以找到许多共同话题。当然它不局限于职业，也可能是别人问你是什么行业的，学的什么专业等。\u003c/p>\u003cp>&nbsp;一般在一些多人活动、聚会的现场，与陌生人面对面时特别适合，当然在一些需要介绍自己的工作但是又比较不被人熟知的岗位、行业时，或者在比较尴尬的相亲初次见面时。\u003c/p>\u003cp>&quot;我们再来回顾下具体步骤（纸头展示步骤）： \u003c/p>1、先把自己的职业、行业具像化，（比如写代码的最终形成的产品是什么，比如是生产零件的，一般它会变成什么产品的配件等等。）\u003cbr>2、把这个产品更加的生活化，将它放到我们日常生活会接触的场景中（比如我案例中的电商促销活动，到小朋友的用品，到生鲜蔬菜，把几个不同的场景例给对方。要适合不同年龄、人群的几个可能。）\u003cbr>3、熟记于心。（当你遇到被这样问时就可以用起来了。帮助你缓解氛围，让彼此可以找到更多接下去的话题。）\u003cbr> &nbsp; \u003c/td>\u003c/tr>\u003ctr>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>来说说你们的职业，看看今天现场的都有哪些，根据不同特点我们看看是属于特别抽象的。（对不同职业做一个简单的引导）\u003c/p>\u003cp>麋鹿：我是做银行渠道的\u003c/p>\u003cp>拆书家：是贷款吗？\u003c/p>\u003cp>麋鹿：不是，贵金属的。\u003c/p>\u003cp>拆书家：哦那你可以从各类理财产品、贴近生活的词汇去引导。\u003c/p>\u003cp>虾条：我是做测试的。\u003c/p>\u003cp>拆书家：那你可以从支付宝、美团、大众的app去入手，有没有出现过点击不跳转啊、点进去弹出啊等角度切入。\u003c/p>\u003cp>拆书家：嗯球球你的职业医疗器械和片段有类似的，我就不帮你拆解了。天鹏是产品，我已经做了解释了。好那我们进入a3环节。\u003c/p>\u003cp>a3:\u003c/p>\u003cp>场景设计\u003c/p>\u003cp>假设现在你在一个活动现场，有很多陌生的人，当时都是各行各业的精英。如果可以和现场的人建立关系，都是很棒的人脉。那么我们两两一个小组，扮演现场的参与人员，用镜头片段中的方式“你是做什么职业的呀”这个问题来切入对话，不让彼此快速结束对话或者陷入尴尬的冷场。让自己成功的与对方可以建立起一些联系。一会儿邀请一组来演示下。\u003c/p>\u003cp>参与者案例：\u003cbr>\u003c/p>\u003cp>A：菲妮，你是从事什么职业的呀？\u003c/p>\u003cp>B：你有没有用过防水手机或者防水耳机呀？这种手机扔到水里还能放音乐呢。我就是做这个零部件的销售的。\u003c/p>\u003cp>A：那好厉害，下回要买这类产品可以找你咨询呢。\u003c/p>\u003cp>／／（互换）／／\u003c/p>\u003cp>B：你是做什么职业的呀？\u003c/p>\u003cp>A：我们手机都有视频app，播放软件等，很多企业没那个经历自己去开发，就会去用别的公司服务。我们就是提供这个开发的。他们要用这些东西就比较在意质量，我就是去维护这个质量保证的。\u003c/p>\u003cp>拆书家反馈：\u003c/p>\u003cp>我觉得这个很棒，把测试这个生硬的词用了质量保证来解释说的特别具象化。并不是直接说出岗位，尤其有些技术类职业，对方并不是对职业感兴趣，只是找共通点。所以你这个解释特别好。\u003c/p>\u003cp>总结语：\u003c/p>\u003cp>我再给大家说下这个操作方法：\u003c/p>\u003cp>1、先把自己的职业、行业具像化\u003c/p>\u003cp>2、把这个产品更加的生活化，将它放到我们日常生活会接触的场景中\u003c/p>\u003cp>3、熟记于心\u003c/p>\u003cp>希望今天的片段的方式方法可以给大家在接下去与陌生人接触时帮助你们破冰，建立更多的人脉关系。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500210396000,"updated_at":1504589422000,"ria":true},{"id":3159,"topic":"如何展开一场有趣的对话","learn_goal":"通过对话的四条原则来逐步学会如何摆脱沟通和对话中的陈词滥调","remark":"书中着重强调了：“一个对其他人发自内心感兴趣的人，在两个月里创造的沟通，要比一个总是试图让别人对自己感兴趣的人在两年内创造的沟通还要多。”","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"什刹海","city":"无锡"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"1.分组环节：开始前咱们先分下小组，每个小组大概是3-4人，就先按照现在的座次来分，这里是第1组，2组，那边就是3组，还有这边是4组\r\n2.自我介绍&书和作者的简介：\r\n大家晚上好！首先给大家做一下简单的自我介绍，我是李朋三，目前是一名拆书帮的龙城二期的高级学员\r\n今天我要拆的这本是《凸法则-从默默无闻到脱颖而出》，本书作者是【美】山姆.洪恩,她是一位心理学家，风靡全球的心理学、沟通学畅销书作家，书中所讲“凸法则” 是一种运用心理学，达到“知己知彼”状态的竞争法则：揣摩决策者需求点、挖掘自身的优势、创新思路、高效率传达信息，从而快速获得决策者的兴趣、信任和认可。\r\n今天分享的便签是我的TF1-2：如何开始有意义的沟通对话？","ratings_count":0,"texts":[{"id":5980,"quote":"\u003cp>【R阅读原文片段】\u003c/p>\u003cp>下面是我给他的四条建议，教给他如何摆脱陈词滥调（没人对这些感兴趣），开始有意义的对话和沟通。\u003c/p>\u003col>\u003cli>\u003cp>\u003cstrong>别在开始就问那些老掉牙的问题。\u003c/strong>\u003c/p>\u003cp>无聊的问题总有无聊的答案。试试“你激动万分的工作进行得怎么样啦？”或“你周末一般做什么啊？”\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>寻求意见。\u003c/strong>\u003c/p>\u003cp>杂志创始人马尔克姆.福布斯说：“要抓住男人的心，首先要抓住他的意见。”抓住任何人的心都是要通过抓住他们的意见。问一句“你有什么意见吗？”就相当于发送了一条信息，即你认为他有智慧可以分享，而且你十分欢迎他的分享。没了填鸭式的陈词滥调，你正走向富有成效的交流之路。\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>使用“跟我讲讲”这个魔法词语。\u003c/strong>\u003c/p>\u003cp>很多人在一开始谈话的时候问封闭式问题，结果对方一个词语就可以结束对话了。比如：“你喜欢这次商会会议吗？”对方回答：“喜欢。”\u003c/p>\u003cp>“跟我讲讲”这个魔法词语会把蜻蜓点水式的交流变成深刻、更有意义的对话，让你们真正了解一个人。比如：“我错过了这次商会会议，你能跟我讲讲都谈了哪些内容吗？”\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>折回谈话。\u003c/strong>\u003c/p>\u003cp>每次他人说完之后，你都面临一个选择。你可以接着说“我……”也可以说“你……吗？”折回谈话。如果每次别人说完之后你就开始谈论自己，别人就会丧失继续谈话的兴趣。\u003c/p>\u003cp>比如你问：“现在的商会主席是谁啊？”\u003c/p>\u003cp>对方回答：“朱迪.格雷。”\u003c/p>\u003cp>你接着说：“哦，我知道朱迪，她就住在我们小区，我记得有一次……”\u003c/p>\u003cp>唉。以“我”开头的句子让注意力都集中在我们的感觉和观点、我们所知道的和所做过的事情上。\u003c/p>\u003cp>如果你接着抛出一个以“你”开头的问题，那情况就大有不同了。感受一下，如果你得到回答后接着说：“哦，现在的主席是朱迪啊，你知道她今年的商会目标是什么吗？”\u003c/p>\u003cp>以“你”开头的问题让注意力到集中在对方身上。人们能够感受到你的真诚，你是真正想要了解他们的，因为你确实是如此。\u003c/p>\u003c/li>\u003c/ol>","explains":"\u003cp>接下来给大家分享我的一个案例 \u003c/p>\u003cp>上周五（6月30日）上班路上，碰到了同事小郑，既然碰到了总得说话吧，先说了“早啊”然后就是“早啊”，最近工作忙不忙？不忙！后来我觉得这样说多尴尬啊，后来我就主动说了最近工作中遇到一个项目，说了一堆，但是他感觉不感兴趣，这有点不好说了。\u003c/p>\u003cp>这样的沟通过程并不是我们所希望的。可是要怎么聊呢？\u003c/p>\u003cp>主要还是在聊天过程中没有找到一个对方感兴趣的话题，或者就是我以为Ta一定感兴趣这个话题，那其实他并不感兴趣，\u003c/p>\u003cp>（How）那如何才能摆脱陈词滥调并开始有意义的沟通对话呢？原文中作者给出了四条原则\u003c/p>\u003cp>第一，不要以无聊的话题来开始与对方的对话。避免无聊话题开头，比如： “早啊”可以换作“哎，听说你们家最近又买了一套房子是吧”\u003c/p>\u003cp>第二，向对方征求意见。比如：最近项目中有个问题想请教下你，你觉得怎么办会比较好？\u003c/p>\u003cp>第三，“跟我讲讲”让沟通变得有意义。聊天中避免询问封闭性的话题，因为会没有下文，比如：最近忙不忙？不忙。”可以换作“你买房子的时候跟中介怎么聊的，能不能跟我讲讲呢？”\u003c/p>\u003cp>第四，引用“你”开头的问题，折回谈话\u003cstrong>。\u003c/strong>比如：和同事聊天中我一直在说我自己的事，替换为“哎。现在买房子好中介不好找啊，你觉得怎么找才能遇到好中介呢？”\u003c/p>\u003cp>于是读了这个片段后我就在上周末的部门聚餐中又碰到同事小郑了，就用了以上方式跟他聊天，找到他感兴趣的话题——钓鱼，我就问他如何钓鱼啊？他就跟我讲如何打窝，选什么位置，什么时间什……他聊的非常的嗨，我听了也涨知识，那这种情况非常好。\u003c/p>","interaction":"\u003cp>【A1】激活经验\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>接下来请大家回想一下，我们平时在与别人沟通交流的时候，有没有因为找到的话题太过于“老掉牙”或者是过于封闭， \u003c/p>\u003cp>可以是和家人孩子的、朋友同事的，比如说为什么家人朋友总是对我的谈话不感兴趣呢？等等。\u003c/p>\u003cp>相信大家都遇到过上述这样一次或者多次沟通对话不愉快经历。那下面就先请大家按照咱们刚才的分组进行分享讨论，\u003cstrong> \u003c/strong>\u003c/p>\u003cp>首先给大家2分钟的时间回想下过去发生的案例并用咱们手中的便签记录下来，好，我们现在开始。（2min后）写好的伙伴在各自小组内先进行小组分享，然后时间同样给大家2分钟，（4min后）\u003c/p>\u003cp>好，时间到，下面请一个小组的小伙伴给大家分享下她过去的案例，好，就你了（时间控制在1~2分钟）\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>曹欧：工作在教育系列的，一开始工作是从销售开始，做销售的时候，先做采单，然后就在幼儿园门口采单，采单了一位妈妈完成后（记得她当时在吃烤山芋），在接下来的回访中开头聊天是：我说：“某某妈妈你是不是特别喜欢吃烤山芋啊？”她说：“没有啊”；接下来自己就不知道该怎么聊了。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>谢谢刚刚的小伙伴给我们分享她自己的案例，一开始她问的虽然是以你为开头的问题，但是后来话题断开了（封闭性提问）或者在提问找到她的感兴趣的话题然后说“跟我讲讲”会更好些。\u003c/p>\u003cp>那么接下来请大家根据今天所学到内容写出自己想在未来的一周内或者一个具体的时间点尝试的行动计划，\u003c/p>\u003cp>不是想法，而是有具体的行动，抛开那些“老掉牙话题”和“我要说……”，并请大家用便签记录下你自己的行动计划内容（比如说用到片段中的一条或者两条建议即可）付诸行动并给自己一个行动期限，时间是1.5分钟，完成后请大家向我举手示意，好，现在开始……\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>小刘：因为自己外出念大学的缘故，平时就很少能跟弟弟聊天沟通了，那基本上也不知道从何聊起，学习了今天的片段后，就计划在明天下午弟弟上完补习班以后呢，运用片段中的“跟我讲讲”原则问他：1.今天的课上都学到哪些啊？2.学习了书法课一段时间了你觉得现在写字比较之前有哪些不一样呢？能否跟我讲讲呢，相信一定会是一次愉快的姐弟沟通\u003c/p>\u003cp>小结：好，看到大家基本上都已经写好便签了，其实大家发现了吗？通过学习今天的四条沟通原则，真的可以让对方感受你的真诚。期待大家在今后的日常工作和生活中继续使用我们今天学到的沟通方式，并把它转化为我们的沟通交流技能。\u003c/p>\u003cp>今天我的TF1-2分享到此结束，感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1499598674000,"updated_at":1499690205000,"ria":true},{"id":2795,"topic":"如何开始一次有意义并令对方感兴趣的对话","learn_goal":"通过对话的四条原则来逐步学会如何摆脱沟通和对话中的陈词滥调","remark":"书中着重强调了：“一个对其他人发自内心感兴趣的人，在两个月里创造的沟通，要比一个总是试图让别人对自己感兴趣的人在两年内创造的沟通还要多。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"什刹海","city":"无锡"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"我们先进行小组分配，那我们根据座次3人一组，一会儿拆书的过程中需要小组讨论的时候请大家按照分配好的小组进行讨论。\r\n大家晚上好！首先给大家做一下简单的自我介绍，我是李朋三，职业是一名在公司管理精益项目的工程师，\r\n今天我要拆的书籍是《凸法则-从默默无闻到脱颖而出》，作者是【美】山姆.洪恩,今天分享的便签是我的TF1-2：如何开始一次有意义并令对方感兴趣的对话？","ratings_count":0,"texts":[{"id":5555,"quote":"\u003cp>【R阅读原文片段】\u003c/p>\u003cp>下面是我给他的四条建议，教给他如何摆脱陈词滥调（没人对这些感兴趣），开始有意义的对话和沟通。\u003c/p>\u003col>\u003cli>\u003cp>\u003cstrong>别在开始就问那些老掉牙的问题。\u003c/strong>\u003c/p>\u003cp>无聊的问题总有无聊的答案。试试“你激动万分的工作进行得怎么样啦？”或“你周末一般做什么啊？”\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>寻求意见。\u003c/strong>\u003c/p>\u003cp>杂志创始人马尔克姆.福布斯说：“要抓住男人的心，首先要抓住他的意见。”抓住任何人的心都是要通过抓住他们的意见。问一句“你有什么意见吗？”就相当于发送了一条信息，即你认为他有智慧可以分享，而且你十分欢迎他的分享。没了填鸭式的陈词滥调，你正走向富有成效的交流之路。\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>使用“跟我讲讲”这个魔法词语。\u003c/strong>\u003c/p>\u003cp>很多人在一开始谈话的时候问封闭式问题，结果对方一个词语就可以结束对话了。比如：“你喜欢这次商会会议吗？”对方回答：“喜欢。”\u003c/p>\u003cp>“跟我讲讲”这个魔法词语会把蜻蜓点水式的交流变成深刻、更有意义的对话，让你们真正了解一个人。比如：“我错过了这次商会会议，你能跟我讲讲都谈了哪些内容吗？”\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>折回谈话。\u003c/strong>\u003c/p>\u003cp>每次他人说完之后，你都面临一个选择。你可以接着说“我……”也可以说“你……吗？”折回谈话。如果每次别人说完之后你就开始谈论自己，别人就会丧失继续谈话的兴趣。\u003c/p>\u003cp>比如你问：“现在的商会主席是谁啊？”\u003c/p>\u003cp>对方回答：“朱迪.格雷。”\u003c/p>\u003cp>你接着说：“哦，我知道朱迪，她就住在我们小区，我记得有一次……”\u003c/p>\u003cp>唉。以“我”开头的句子让注意力都集中在我们的感觉和观点、我们所知道的和所做过的事情上。\u003c/p>\u003cp>如果你接着抛出一个以“你”开头的问题，那情况就大有不同了。感受一下，如果你得到回答后接着说：“哦，现在的主席是朱迪啊，你知道她今年的商会目标是什么吗？”\u003c/p>\u003c/li>\u003c/ol>\u003cp>以“你”开头的问题让注意力到集中在对方身上。人们能够感受到你的真诚，你是真正想要了解他们的，因为你确实是如此。\u003c/p>","explains":"\u003cp>若要在沟通交流中摆脱陈词滥调并达成一次有意义并且让对话感兴趣的对话，我们通常可以遵循以下四条原则\u003c/p>\u003cp>第一，切忌不要以无聊的话题来开始与对方的对话\u003c/p>\u003cp>第二，向对方征求意见\u003c/p>\u003cp>第三，引入“跟我讲讲”让交流变的更加深刻有意义\u003c/p>\u003cp>第四，抛出以“你”开头的问题，折回谈话\u003c/p>\u003cp>下面先分享下我自己的案例，\u003c/p>\u003cp>记得上大二的时候，遇到过一个姑娘，觉得她很好，然后-我就要到了她的QQ号，（因为那时候还没有微信）以为自己的美梦就此可以开始了。\u003c/p>\u003cp>顺利的通过了她的验证后，就开始的时候就说一些：自我介绍，你好之类的话，对方也还能及时回复，\u003c/p>\u003cp>但后来在聊天的过程中，我就只会说：“早饭吃了么，晚饭吃的什么啊！”这些无聊的问题。可是等她回复了之后呢，\u003c/p>\u003cp>要么我就没有了下文，要么就是听她说完我就开始讲今天自己做了些什么事说半天（也没管她是不是愿意听），然后她就愣了好半天不说话，最后说个好梦结束了，时间长了以后我再发信息人家也不回了，然后就没有然后了。从那以后自己心里一直就有个疙瘩，怎么对方不太愿意搭理我呢！唉，一言难进\u003c/p>\u003cp>直到最近我学习了本片段之后啊，才发现原来是这样啊，于是我就开始实际运用了。\u003c/p>\u003cp>也就是在昨天（5月23日）公司午休时，在休息室碰到了同事小杨，听大家说他最近在买房子，\u003c/p>\u003cp>1.所以我就好奇问他：“你最近家里买房子的事情张罗的怎么样了啊？”他显得蛮高兴的，说：“买的二手房，刚拿到钥匙，下周就准备搬家啦！”\u003c/p>\u003cp>2.我接着又问：“效率这么高啊，都拿到钥匙了，我最近也计划去了解下买二手房的事情，对这方面正好不太懂，能跟我讲讲你当时购买二手房的时候怎么和中介，房主谈判的么？”\u003c/p>\u003cp>他一看我对他的购房过程感兴趣，就开始详细的跟我说起来。\u003c/p>\u003cp>3.不一会听他说完后，觉得他的购房经历对我很有启发，（原本我是准备跟他描述我的看房经历，后来想想，这样的话肯定又是“以我开头的”陈词滥调了）\u003c/p>\u003cp>然后我就又问他：“你的房产经纪人是谁啊？你知道他从业多久了么，佣金最低大概需要多少啊？”接着他给我简单介绍了下，不但给了我联系方式而且还附赠我一些跟中介打交道的谈判技巧。\u003c/p>\u003cp>这次聊天很愉快，并且最后同事跟我说，如果到时候我自己把握不准，他可以和我一同参与和中介房东的沟通，意外收获的感觉。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1（激活经验）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>接下来请大家回想一下，我们平时在跟别人沟通交流的时候，有没有因为找到的话题单一、枯燥、无聊、没有任何意义、话题太封闭或者总是“以我开头的”不断诉说自己的感觉和观点的沟通交流的经历呢？\u003c/p>\u003cp>可以是和家人的、孩子的、同学同事的，甚至是朋友之间的，比如恋爱开始时，对方总是对你的聊天不感兴趣；孩子宁愿在家打游戏也不愿意跟你说话；爸妈总是怪我不会和别人聊天；为什么朋友总是不愿意跟我敞开心扉呢？看他平时和别人挺能聊的啊，等等。\u003c/p>\u003cp>相信大家都会遇到上述这样一次或者多次沟通交流不愉快纠结的经历哦。那下面就先请大家按照咱们刚才分成的各个小组进行分享讨论，\u003c/p>\u003cp>首先给大家2分钟的时间回想下过去的案例并用便签记录，（2min后）写好的伙伴在各自小组内分享，同样给大家2分钟，（4min后）\u003c/p>\u003cp>时间到，下面请一个小组的伙伴给大家分享下，分享时间请控制在2分钟内。\u003c/p>\u003cp>\u003cstrong>学习记录：\u003c/strong>\u003c/p>\u003cp>梅姐：平时在家时，经常与儿子沟通交流家庭作业方面的问题产生了一些不愉快的小分歧\u003c/p>\u003cp>\u003cstrong>A2（催化应用）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>谢谢刚刚的小伙伴给我们分享他自己的案例，案例中提到了她们母子之间因为家庭作业引起的一次不愉快的经历，如果能够添加下“跟我讲讲”这条原则引出对方刚兴趣的内容和话题，那么谈话效果应该会更好些。\u003c/p>\u003cp>那么接下来请大家根据今天我们所学的“感兴趣对话的四条原则”，写出自己想在未来的一周内或者一个具体的时间点尝试的行动计划，\u003c/p>\u003cp>不是想法，而是有具体的行动，先停止陈词滥调和不断叙述自我，然后通过四条原则逐渐学会与对方开始一次有意义并令对方感兴趣的对话，便签记录行动计划的内容只需要引用一条或者两条建议即可\u003c/p>\u003cp>最后付诸行动并给自己一个行动期限，时间是1.5分钟，完成后请大家向我举手示意，好，现在开始……\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>孙老师近期跟进了一个项目，跟客户沟通时总是发问一些项目相关的事情，很少关注客户，正好借着六一节临近的时机，运用“跟我讲讲”法则来跟客户简单聊聊关于孩子教育的话题\u003c/p>\u003cp>\u003cstrong>小结：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>好，看到大家基本上都已经写好便签了，其实大家发现了吗？通过今天四条原则的学习与认知，真的可以让我们和别人\u003cstrong>开始一次有意义并令对方感兴趣的对话\u003c/strong>。让我们和别人沟通交流时更加的愉快。期待大家在生活中继续使用我们今天学到的令人愉悦的沟通的方式，让这种方式带给我们愉悦、开心的有效的沟通。让它转化为我们的沟通交流技能。\u003c/p>\u003cp>今天我的TF1-2分享到此结束，感谢大家的参与。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496365699000,"updated_at":1496365714000,"ria":true},{"id":2761,"topic":"余佳桐TF2-1定级","learn_goal":"完成定级","remark":"演讲技巧","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"余佳桐","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"大家好，我是今天带领大家拆书的拆书家余佳桐，我从两个方面简单的介绍下我自己，在工作中，我的职业是 “理财规划师”主要的工作就是根据客户的理财目标，帮助个人或者家庭提供财务规划建议，主要使用的工具是境外的资产或境外保险。\r\n在生活中，我给自己的便签是“文艺”，愿意去参加此类的思维碰撞的社群活动，自己私底下则喜欢电影、拍照，偶尔也写些文字。","ratings_count":0,"texts":[{"id":5512,"quote":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>今天进行的是TF2-1的定级。在最开始之前，我先简单的给大家说明下今天的学习目标：希望通过今天RIA的学习可以让大家学会“示人以鱼”的表达方式，也就是使用视觉+提问的开场方式，迅速吸引互动对方的注意力，而达成我们的沟通目标。今天现场有4个伙伴，接下来相邻的两两一组，分2组，可在之后的讨论分享环节进行互动交流。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>【FAB图书介绍】\u003c/strong>\u003c/p>\u003cp>今天我将要带拆的这本书叫《凸法则》，\u003c/p>\u003cp>【F特征】这本书出自作者山姆洪恩，心理学家、国际演说家、沟通策略师，曾经为美国联邦政府机构人员和世界顶级企业家CEO，开设了专业的沟通心理课程。\u003c/p>\u003cp>【A优势】： 在同类经管、畅销书中，这本书就显得真实、直接、有效，而且极具可操作性。\u003c/p>\u003cp>【B利益】：你有没有一张口就失去观众的困惑？同样一件事，有的人讲大家会很感兴趣、而你说完，别人只会低头玩手机，礼貌点的会回应你一句“哦 这样啊”。如果这是你的困惑点，或许这本书就能帮到你。\u003c/p>\u003cp>\u003cstrong>R片段\u003c/strong>\u003c/p>\u003cp>企业家卡里·卡特，深知“示人以鱼”的重要性。那时，卡里正在参加一个竞赛，名叫“海豚坦克”（比电视真人秀节目“鲨鱼坦克”或“进入龙穴”稍温和、更有同情心的版本，创业者向投资者评审小组力荐自己的产品获得投资。）\u003c/p>\u003cp>作为评审员，我有机会提前浏览了卡里的商业计划。他创造了一个吊钩，取名叫卡钩，可以放在车里，用于挂手提包。我当时想：不会是真的吧，我要用一个挂手提包的挂钩开创生意？然而，卡里在第1分钟内就调动了所有人的兴趣。她把一个全尺寸汽车座椅拖到房间里前面，放在旁边的地板上，然后把手提包挂在上面。他站起来，面对大众围着虚构的方向盘转动自己的手指，然后一边开始“驾驶”一边说：\u003c/p>\u003cp>你有没有经历过这种情况：车开着开着却要突然停下来？你的手提包从座位上掉下来，手机摔了出去。于是你一边乱扒摸索，试图捡回来，一边停留在大路上……想象一下,如果你从此再也无需担心手提包掉下去会怎样?想象一下,如果有一个吊钩你可以……\u003c/p>\u003cp>这时候，一个人站起来说：“我要2个，1个给我妻子，一个给我女儿。”\u003c/p>\u003cp>哇哦。卡里从一个不敢相信的“真的吗？”开始，变成在1分钟之内“我买2个”的激情，这就是展示和询问的力量。卡里还有几件事情都做得十分聪明，这也让他更会抓获和保持人们的注意。\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>他用道具帮助我们看清楚他在说什么。\u003c/strong>\u003c/p>\u003cp>要把那个汽车座椅搬进长滩会议中心当然挺麻烦的，不过去很值得，因为他创造了好奇心。我们都在想：你搬这个东西要做什么？卡里没有成为另一个“喋喋不休”的人而是甚至在开口之前就已经抓获了我们的注意力。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>他让我们看到\u003c/strong>\u003c/p>\u003cp>我们的视线在哪里注意力就在哪里如果我们不注视者演讲人意味着我们也没有在听演讲卡里展示给我们有趣的东西看因此我们把注意力集中在她身上而不是低头看手机\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>他以问题开场 \u003c/strong>\u003c/p>\u003cp>他没有一开始就描述自己的方法，而是展示了一场“火”（这里指一个麻烦和问题）让我们想要他的“灭火器”（这里指他对上述麻烦和问题的解决方案）。我们记得自己或爱的人曾经发生过那种麻烦，所以自然想要他的产品以防麻烦再次发生。\u003c/p>","explains":"\u003cp>在今天R片段中的主人公卡里，他有个好的产品项目，想要在众多的创业者当中脱颖而出，让投资人对他的产品感兴趣，并获得投资。他用了直观的道具和提问带入困境的方式达成了目标。\u003c/p>\u003cp>其实像类似这样，人和人的展示互动其实生活中非常的常见，比如说你有一个好的产品，或者你有一个好的方案，推荐给你客户或者上司，我们如何在展示的过程中去吸引对方的注意力，这是我们所关心的问题。关于怎么做到？我来说个例子。\u003c/p>\u003cp>【一般情况的做法】\u003c/p>\u003cp>比如上上周我去了朋友工作室，她主要做塑性衣的。以往她在给客人推荐一件塑形衣，会是一边跟客人泡茶，一边交流说她的产品的材料的高科技面料可以让细胞共振，以达到瘦身的效果....\u003c/p>\u003cp>【不这么做的坏处】通常这样的展示方式客户不太受用。\u003c/p>\u003cp>一、客人容易分心去做其他事情\u003c/p>\u003cp>二、因为产品价格不便宜，很容易让客人因为价格高，而拖延购买或者放弃购买。最终没有达到销售的目的。\u003c/p>\u003cp>后来他们转变的方式，设置了试衣间，这个试衣间有个很大的特点就是，里面放置了一面很大的镜子，当客户去到试衣间试穿时，他们首先会让客人不穿外衣的在镜子面前直观的审视自己的身材，然后不经意的说：因为缺少运动，随着年龄的增长，腰围的宽度会以每年0.5-1公分的增长，因为地心引力多余的脂肪会以每年0.2公分下垂。想象下，如果我们没有进行保养5-10年后我们是怎样的自己？然后让客人在镜子面前穿上塑性衣，看到自己身材被优化后的自己，然后说“穿上这个3-5个月，腰围可以较现在瘦2-3公分”，穿的时间越长约明显，以后你即使脱掉这身，也可以有S曲线的身材，想象一下那是一个怎么样精神状态的自己？自从运用这个方式，朋友工作室的业绩蹭蹭上升了。\u003c/p>\u003cp>而我朋友之前的方式这个转变其实就是R中“示人以鱼”的方式。还记得吗？她用客户的身材痛点用镜子的方式展现给她。再来，她用淡淡询问的方式，来引发客人的思考“如果你不这么做的话，几年之后可以想象出是一个怎么的状态吗”以上。&nbsp;\u003c/p>","interaction":"\u003cp>【显性问题】\u003c/p>\u003cp>好的，现在大家回想一下，这几周你是不是有过这样的时候，你有一个很棒的方案，想让你的老板接受。或者有个很棒的产品想要你的客户接受，你踌躇满志的说着，对方好像就是GET不到。这件事发生在什么时候？是一件什么事？大家花2分钟时间在组内讨论一下，等会我会请2位伙伴来分享。\u003c/p>\u003cp>\u003cstrong>学习者 小蒋：\u003c/strong>\u003c/p>\u003cp>这是一个，跟上司沟通方案，却没有成功的例子。我是一个企业培训师，这几周都在忙领导力项目和总部培训的课程资料。可是上周我的上司突然向我追店长培训项目。我虽然是想让上司可以根据课程准备，尊重我的工作进度，按照先后顺序来合理安排。可是因为手上事情很多，而且他的要求又非常的突然，我当时就急着说明我现在遇到的问题。而对方以为我不愿意做，最终不欢而散。\u003c/p>\u003cp>后来我就换了一种方式。首先，我做了一份近期我的工作安排进度表，让我的上司直观的看到我手上的工作进程。再来，我通过询问的方式提出说，如果按照目前的时间进度安排，仓促的做一份店长培训项目不是不行，只是追求速度做出来的方案，真的可以帮我们解决问题吗？如果我们按照进度安排，根据现在店长管理出现的问题进行充分的市场调研，再做出来的店长培训，这两种结果我们会更希望哪一种呢？后来上司接受了我的建议。\u003c/p>\u003cp>拆书家：谢谢小蒋，她举的这个以往的经历也很好的呼应了R中的知识点。因为时间的问题今天就只问1个伙伴咯。\u003c/p>\u003cp>\u003cstrong>总\u003c/strong>\u003cstrong>结\u003c/strong>\u003c/p>\u003cp>最后，其实不只是工作当中，在生活上，比如你想要换沙发、换装修需要跟老公商量，此类的，需要让另一方接受你的提议的情境，你都可以用到“示人以鱼”的方式进行表达，呼吁大家都多加运用起来吧。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496124781000,"updated_at":1496126945000,"ria":true},{"id":1973,"topic":"潇潇荷3-3定级","learn_goal":"通过学习如何在一分钟内进行吸引人注意力的产品介绍货自我介绍，","remark":"","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"潇潇荷","city":"南京"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"学习目标：通过片段学习如何在一分钟内进行吸引人注意力的产品介绍或自我介绍以及打破与陌生人初次交流时的僵局。\r\n大家好，我是今天的拆书家潇潇荷，非常欢迎大家来参加我的3-3定级，今天我所带拆的这本书是《凸法则》。\r\n1、事件场景 ： 在过去你有没有过这样的经历？遇到了某位你仰慕已久的大咖，想和他进行深入交流，却不知道从何谈起。某个你渴慕已久的企业，你想和他建立合作伙伴关系，却羞于开口。某家你特别想加入的企业，终于放出了适合你的工作职位，你却不知道如何从激烈的竞争中脱颖而出。\r\n2、提问：面对这类问题，当时是不是觉得很沮丧？完全不知道怎样将自己更好的地方呈现给别人呢？\r\n3、影响：如果这些机会错失的话，可能会让你沮丧不已。俗话说，机不可失，失不再来。\r\n4、解决：今天我带拆的这本书是《凸法则》，在本书中作者提出的，新颖、高效、给予、有用等七个法则，可以快速地帮大家在别人心目中留下良好印象，轻松搞定竞争对手客户面试官和一切你征服的人，达到一鸣惊人的效果。","ratings_count":0,"texts":[{"id":4586,"quote":"\u003cp>你知道吗？以前通常要花将小时才能预定一次五站式旅行。\u003c/p>\u003cp>你知道吗？以前通常要花5天才能收到一个五站式旅行的报价。\u003c/p>\u003cp>想象一下，如果破天荒地有一次，你可以自己计划和预定一次五站式旅行，不再需要旅行社会怎样？&nbsp;&nbsp;\u003c/p>\u003cp>想象一下，如果你能得到多站式旅行自己的报价呢？&nbsp;\u003c/p>\u003cp>&nbsp;想象一下，如果你能在不到1小时内把上述事情都做完呢？&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;其实你不必想象了，我们已经创造出来了，它就叫作Indie。\u003c/p>\u003cp>&nbsp;好奇了吗？成千上万的人看过那个视频后也十分好奇，于是点击链接，想了解更多信息。\u003c/p>\u003cp>&nbsp;在出版行业怎么使用这个开场白的例子想好了吗？假设你正在写―本关于如何在如今这个僧多粥少的时代找到工作的电子书，那么你可以这样开场：&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;你知道吗？2012年有360万个职位空缺，80％没有刊登出来。&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;你知道吗？平均每一份工作有118个人中请，而得到面试机会的人只有20％。\u003c/p>\u003cp>&nbsp;你知道吗？2013年美国53.6％的25岁以下学士没有工作者没有充分就业。\u003c/p>\u003cp>&nbsp;想象一下，如果你能打听清楚未被刊登的优质工作会怎样？\u003c/p>\u003cp>&nbsp;想象一下，如果你能大幅增加本周面试机会会怎样？\u003c/p>\u003cp>&nbsp;想象一下，如果你能在如今这个竞争超级激烈的就业市场上，学到10种新的久经考验的方式让自己脱颖而出会怎样？&nbsp;\u003c/p>\u003cp>&nbsp;&nbsp;其实你不必想象了，这本的60页的电子书分享了现实生活中的成功案例，他们凭借这些技能在3个月内成功找到工作。实际上…\u003c/p>\u003cp>&nbsp;&nbsp;大多数“直接告诉他们你将要在书中讲什么”的开场白让人以为你在侮辱别人的智商。相比而言，这个开场白更有趣，不是吗？现在就开始这样开场吧！\u003c/p>","explains":"\u003cp>在这个片段中，作者向我们展示了怎么样在短时间内创造令人惊艳的开场，瞬间抓住听众们的注意力。在这个酒香也怕巷子深的年代里，我们已经不能静静地等着他人来发现我们的内秀美，必须主动的将自己推销出去，才能获得更多的机会。我们在读一本书或看电视剧时，如果开头没有足够的吸引力，我们便会放弃，不会有足够的耐心去看后续内容，有没有精彩的地方。\u003c/p>\u003cp>有人说：你的命运就取决于自己给人留下的印象，事实也就是如此。刚开始没有留下足够好的印象，谁会注意到你呢？可能会使自己白白错失很多机会，尤其是在情况十分紧急的情况下。\u003c/p>\u003cp>现在有一个说法叫&quot;黄金三十秒&quot;，如果你不能在最初三十秒吸引对方注意力，你将永远错失机会。虽然这个说法有些夸张，但我们也可以感觉到在最初的一段时间给对方留下良好印象的重要性。\u003c/p>\u003cp>我们经历过各种方式的自我介绍，求职，参加活动等等。回想一下自己求职时，面试官说你做一下自我介绍吧，我们都是怎么说的呢？我叫什么，毕业于哪个学校，等等，将简历上的内容又复述了一遍。\u003c/p>\u003cp>这种方式的自我介绍没有出彩的地方，面试官也不知道你哪方面特别出挑，录用你之后能给公司带来高价值。\u003c/p>\u003cp>扪心自问，有几个人觉得自己的自我介绍很好的？更多人提起来就头大。\u003cbr>\u003c/p>\u003cp>所以想让对方印象深刻，就得制造出出乎意料，物超所值的效果。\u003cbr>\u003c/p>\u003cp>根据片段中的内容，我将如何在短时间内制造吸引人的开场白提炼为以下三个步骤：\u003c/p>\u003cp>1&nbsp; 以三个令人惊讶的“你知道吗”的问题开始话题，介绍对方不知道但是想知道的事情，例如：讲解内容的紧迫程度，讲解问题的正在满足的未满足需求等。\u003c/p>\u003cp>2&nbsp; 以想象一下继续话题，提供自己的针对“你知道吗”三个问题的解决方案\u003c/p>\u003cp>3&nbsp; 用其实，你不必想象了结束，向对方提供证据，证明自己已经可以提供对方想要的产品或服务。\u003c/p>\u003cp>例如，在原文中，作者利用这种方式，针对旅行产品，自己电子书销售，提供了一个令人惊艳的开场，并且取得了良好的效果。\u003c/p>\u003cp>（适用边界条件）那么是不是所有的场合都适用这样的开场白呢，假如别人要求你做十分钟的介绍，你在一分钟之内全部介绍完了，那么接下来你说什么呢？而且，开场太精彩会让人对你有太好的期待，如果后面的介绍后继无力，反而会适得其反。这种开场方式，更适合在极短时间内，一两分钟内吸引人注意力的介绍。\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们知道，短时间内提供让自己话语更有吸引力可以用这样的句式：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“你知道吗？”疑问起头，“想象一下”引导他人思考，“其实，你不必想象了...”画风一转这样的方式。那么接下来我们请小伙伴两两以小组，运用这样的句式编写个小故事，一段对话。自己设置人物场景事件，包含起因经过结果。给大家三分钟时间，三分钟后，我们请小伙伴来分享你们的小故事。\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例分享：\u003cbr>\u003c/strong>\u003c/p>\u003cp>有一家培训机构正在招聘老师，招聘方要求在一分钟之内介绍自己最擅长的一项，可以是任何特长。例如：思维导图、手绘、培训等等。小王扮演辅导机构的招聘人员，小李扮演应聘者。\u003c/p>\u003cp>小王：我们最近在招聘早教老师，应聘者也挺多的，你觉得你自己在哪些方便有优势呢？\u003c/p>\u003cp>小李：我是一位妈妈，在教育孩子方面也非常有心得，我是985高校的儿童发展方向的硕士，自己也很喜欢学习。\u003c/p>\u003cp>小王：那你自己研究方向有什么突出优势，效果怎样，能简单谈一下吗？\u003c/p>\u003cp>小李：你知道吗？孩子可以自给自足地掌握自己所需要学习的一切。\u003c/p>\u003cp>你知道吗？你所认定的学校可能正在破坏孩子最重要的创造力。\u003c/p>\u003cp>你知道吗？如果你将学习的主动权交还给孩子，他将学习的更好。\u003c/p>\u003cp>想象一下，在一所开放学校环境内，孩子可以自己决定学习进度和方式。\u003c/p>\u003cp>想象一下，孩子的创造力被他自己所激发，该有多好？\u003c/p>\u003cp>其实，你不必想象了，这一切在用正面管教法都能实现，你不来试一试吗？\u003c/p>\u003cp>小王：听着很吸引人的样子，改天我们刚好有个活动，你可以试讲一下哦，如果可以的话，恭喜你成为我们的一员。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":4588,"quote":"—位工程师曾经跟我讲：“小时候，我迫不及待地想要长大，因为我感觉长大了就有信心了。我觉得—旦长大成人，就再也不会害羞或者担心说什么话了。哦，天哪，我错了，哪里有信心药丸呢？“\r\n我告诉他：“要得到信心药丸有—个方法，那就是像关心备至的记者—样对待谈话。记者见任何人都不会害怕，因为他们知道如何回避聊天和真正让人们参与进来。他们问开放式的问题，心无旁骛地倾听，然后跟进直指核心的相关问题。”\r\n他说：“听起来是这样，可是我怎么才能做到呢？”\r\n下面是我给他的四条建议，教给他如何摆脱陈词烂调（没有人对这些感兴趣），开始有意义的对话和沟通。\r\n1、别在开始就问那些老掉牙的问题\r\n无聊的问题总有无聊的答案。试试“你激动万分的工作进行得怎么样啦？”&nbsp;或“你周末一般做什么啊？“\r\n2、寻求意见\r\n杂志创始人马尔克姆福布斯说：”要抓住男人的心，首先要抓住他的意见。”抓住任何人心都是要通过抓住他们的意见。问一句“你有什么意见吗？”就相当于发送了―条信息，即你认为他有智慧可以分享，而且你十分欢迎他的分享。没了填鸭式的陈词滥调，你正走向富有成效的交流之路。&nbsp;&nbsp;\r\n3使用“跟我讲讲”这个魔法词语。\r\n很多人在―开始谈话的时候问封闭式问题，结果对方―个词语就可以结束对话了。比如：“你喜欢这次商会会议吗？”对方回答：“喜欢。”\r\n“跟我讲讲”这个魔法词语会把蜻蜓点水式的交流变成深刻、更有意义的对话。让你真正了解一个人。比如：”&nbsp;我错过&nbsp;&nbsp;了这次商会会议，你能跟我讲讲都谈了哪些内容吗？“\r\n4、折回谈话\r\n每次他人说完之后，你都面临—个选择。你可以接着说“我……吗？”也可以说“你…吗？＂折回谈话。如果每次别人说完之后你就开始谈论自己，别人就会丧失继续谈话的兴趣。\r\n比如你问：“现在的商会主席是谁啊？“\r\n对方回答：“朱迪·格雷。”\r\n你接着说：“哦，我知道朱迪，她就住在我们小区，我记有一次……“\r\n以“我”开头的句子让注意力都集中在我们的感觉和观点、我们所知道的和所做过的事情上。\r\n如果你接着抛出个以“你＂开头的问题，那情况就大有不同了。感受—下，如果你得到回答后接着说：“哦，现在的主席是朱迪啊，你知道她今年的商会目标是什么吗？”\r\n以“你”开头的问题让注意力都集中在对方身上。人们能够感受到你的真诚，你是真正想要了解他们的，因为你确实是如此。","explains":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请问:你们在过去有没有遇到过类似于这种聊天聊不下去，一个问题抛过去，然后就没有下文了的情况？如果有的话是什么话阻碍交流进行？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者一：大年三十问领导，您也要吃团圆饭了吗？领导回答，是啊，然后自己就不知道说什么了，感觉很尴尬。您是不是也不做饭，只等着吃？领导回答：是啊。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：这种问答方式就是提问的封闭式问题，简单用一个是或者否就可以回答的，聊天不能继续。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者二：和朋友经常聊天会问，你在干嘛？别人回答完在干什么之后，就不知道自己要说什么了。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：看来不知道如何将对话继续进行下去是大家共同的痛点。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（通过对比概念和匹配例子引出知识点）我们都希望和对方聊天时信心满满，结束时还有意犹未尽的感觉。然而往往是理想很丰满，现实很骨感。聊天内容除了几句例行的问候之外，例如在干什么呢，吃饭了吗，最近好吗等等，没有别的话可说。我们都期望可以开启一段“持续的沟通”。\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>过年的时向一位我比较敬仰的前辈拜年，发完新年好以后，他给我发了一个红包过来。我就想总不能领完红包后不讲话吧，就想多聊几句。问了下，您家人都回去过年了吗，对方回答是的，我一下子不知道说什么好，觉得很尴尬。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;这是一段“持续的沟通”吗？不是，因为这样的聊天不疼不痒，没有得到任何有价值的信息，并且我也没有发自内心关心对方。对方回答完之后，我就不知道说啥了。\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>其实\u003c/strong>\u003cstrong>回想一下，我真的关心对方有几口人回家了吗？不关心，我只是想随便和对方聊两句，不让气氛那么尴尬，或者领完红包就没话了，太不懂礼貌。也难怪聊天进行不下去。\u003c/strong>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小红和小明在聊天，小红说：“我最近看了个＊＊片子很不错，你看了没？”小明说没有。小红就巴拉巴拉将40集剧情讲了个遍，花了将近一个小时，在这个过程中，小明没有什么回应，觉得很聒噪没意思。小红很委屈，我那么费劲的跟你讲，你为什么还不领情呢？这只是一场“单方面沟通”，不是一段成功的“持续沟通”，中间出了什么问题呢？小红一直在说自己的，压根没有在意对方的感受。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;还有这样的情况，我们和对方聊了几句，好不容易找到一个共同的话题，例如:我发现他也在读这本书，就巴拉巴拉说自己的感觉一大堆，对方只回了一句哦，然后自己很委屈，我已经尽力找话题聊了，为什么得到的是这种回应。你讲自己观点时，有没有想过对方是否认同呢，他怎么接自己话题呢？反之，如果你请教对方的一些收获心得，聊天也许会愉快进行下去。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; 所以，聊天时我们要牢记对方才是核心，我们应发自内心去关心对方，相信没有人会拒绝我们的善心吧。\u003c/strong>\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp; 在这个片段中，作者向提了四条建议，教我们如何开启一段有意义的对话，使沟通持续下去。\u003c/p>\u003cp>第一条：别在开始就问一些无聊的问题。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 问题决定答案。你向别人提出问题的同时，就已经决定了接下来别人提供给你的答案。例如：问一些在你视力所及范围内，对方可能感兴趣的一些事物，不是简单的可以用是或否来回答，类似于你喜欢这件衣服吗？\u003c/p>\u003cp>第二条：寻求意见\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在交流过程中，人们喜欢参与到对话中去，而不是单纯地接收信息。通过“你有什么意见吗？”的询问方式代表了你对对方的认可。\u003c/p>\u003cp>第三条：使用“跟我讲讲”这个句子。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 这个句子可以将原本浮于表面的交流进行的更加深入。\u003c/p>\u003cp>第四条：折回谈话。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 例如当我在和别人交流时，别人向我介绍了一本他非常喜欢的书，这时你有两个选择：一个是将“我”作为主语，向别人介绍下我比较喜欢什么书，读完之后自己有什么样的感触，此时，对方接下来可能不知道如何回答。但当你去问对方你比较喜欢书中的哪个点呢？这是两种选择，一种是以“我做为主语”发表自己的看法、感受或者过去的经历；另外一个是以“你”作为主语，继续将注意力集中在对方身上。折回谈话便是继续以&quot;你&quot;为主语的谈话，当你真正开始关注对方时，会让他收获完全不同的感觉。\u003c/p>\u003cp>&nbsp; 这四条建议可以教我们如何开启一段有意义的谈话，并将交流持续深入进行下去。\u003c/p>\u003cp>这四条并不是严格的执行步骤，只是建议。在交流过程中，可以选择最合适的来使用。\u003c/p>\u003cp>&nbsp; &nbsp;（适用边界条件）&nbsp;虽然使用这几条建议，可以取得不错的沟通效果，但也并不是适用于所有的场合。如果你时间紧迫，聊天时让对方欲罢不成，匆忙结束也不太好是吧？所以，这种沟通方式更适合于时间比较宽松，聊天主题不严格限定的场景。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】自测题目\u003c/strong>\u003c/p>\u003cp>通过第一个片段的学习我们已经知道，如何进行一个可以吸引人注意力的开场，下面我们来做一个测试题，根据自己的实际情况选择适合自己的分数，并将分数相加。1分代表从不，6分代表总是。（分数越高，行动频率次数呈增加的）\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> 交流时，我会把注意力完全放在对方身上。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> 当对方和我有相似的经历时，我会将自己的经历讲出来\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> 每说完一句话，我会思索接下来对方回答起来是否会为难。\u003c/p>\u003cp>4. 交流过程中，我倾向于问开放式问题。\u003c/p>\u003cp>\u003cstrong>解释自测题\u003c/strong>\u003c/p>\u003cp>问卷解释：刚才请大家做的这个小测评，是调查大家在与别人交流的过程中，是否是一个主动参与者。\u003c/p>\u003cp>如果得分在12分以下，说明你的日常交流行为，更多的是将关注点聚焦于自己:我向对方传达出了什么信息，对方接收到后给了我怎样的反馈。\u003c/p>\u003cp>如果得分在12分以上，则说明你是一个主动交流，倾向于更加关注对方，真正地让对方参与到谈话中来。\u003c/p>\u003cp>得分越高，则主动成程度越高。\u003c/p>\u003cp>\u003cstrong>【A3】微行动学习\u003c/strong>\u003c/p>\u003cp>\u003cstrong>接下来进入我们的微行动学习环节。\u003c/strong>\u003c/p>\u003cp>当我们认识新的朋友时，总是困惑于不知道该如何打开聊天局面。那么我们到底应该如何跟陌生人开启一段“持续的沟通”呢，有哪些可行的方案或者思路？请把讨论的可行的做法记录在一张白纸上，10分钟后，我们请每组派代表来讲解你们的成果。\u003c/p>\u003cp>第一组：1.近期发生的热点事情\u003c/p>\u003cp>2. 当下的日期。例如今天是元宵节，我们可以讨论有关汤圆或者花灯的信息。\u003c/p>\u003cp>3.从当下聊天的内容入手，层层挖掘，找到自己和别人之间的共性。\u003c/p>\u003cp>4.关注当下的时间，讨论接下来可以做一些什么事情。例如，饭点去吃饭之类的。\u003c/p>\u003cp>5.观察对方正在做的事。例如，看到对方打字很快，可以猜测对方的职业或者就如何练习打字进行请教。\u003c/p>\u003cp>6.视线范围内，观察静态物品，如饰品等。\u003c/p>\u003cp>第二组：\u003c/p>\u003cp>1.从双方的名字入手，如果别人的名字比较有意思，可以确认下写法，或者是典故之类的。\u003c/p>\u003cp>2.手中正在做的事，假如对方正在玩游戏，可以同他聊一下游戏等。\u003c/p>\u003cp>3.从个人身上的物品入手，妆容，服饰等展开谈话。\u003c/p>\u003cp>拆书家：非常感谢大家提供的这些建议，非常实用，我已经学习到如何与对方开启一段谈话，并进行深入交流了。折回谈话是一个让对话深入进行的非常好的方式，例如方才有位同学提到了，她非常喜欢红楼梦中的某个人物，我对那个人物是有印象的。此时，我可以合同讨论她为什么比较喜欢。\u003c/p>\u003cp>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家布置任务：\u003c/strong>\u003c/p>\u003cp>好的，今天大家回去之后，可以与自己的朋友家人进行一次交流，在交流的过程中尽量使用这四条建议，尝试将注意力完全放在对方身上，而非以个人感受为主。或者用这种方法在咖啡馆或火车地铁上等场所去认识一个新的朋友。希望大家在一周内可以完成，在群里跟大家交流下沟通效果。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者：我下午在星巴克喝咖啡时，邻桌坐了一位年轻帅哥。他正在翻阅采铜老师写的《精进》，刚好最近我也正在看这本书，就想和他交流一下。\u003c/p>\u003cp>就从《精进》入手，采用了折回谈话以及征求意见的方式，同他聊了很长时间，最后还向他推荐了采铜老师的小秘圈，并且还要到了他的微信号码，在本次拆书中学到的小技巧真的非常实用。\u003c/p>\u003cp>\u003cstrong>结语\u003c/strong>\u003c/p>\u003cp>今天我们通过两个片段的学习，了解到如何在开场时做可以吸引人注意力的自我介绍之后，在与对方的交流过程中，尝试将对方做为谈话的核心，了解对方的需求，可以通过给对方带来利益的方式来达到自己的目的，创造互利共赢的局面。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1487401052000,"updated_at":1493642780000,"ria":true},{"id":1971,"topic":"潇潇荷3-1定级","learn_goal":"通过学习克服不知道将自己的优势展现给对方的问题。","remark":"","level":"TF3-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"潇潇荷","city":"南京"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"学习目标：使用这种方式举例介绍自己的长处。\r\n小伙伴们大家下午好，欢迎你们来参加我的3-1定级，今天我带拆的书目是《凸法则》。\r\n开场： 1、事件场景 ： 在过去你有没有过这样的经历？遇到了某位你仰慕已久的大咖，想和他进行深入交流，却不知道从何谈起。某个你渴慕已久的企业，你想和他建立合作伙伴关系，却羞于开口。某家你特别想加入的企业，终于放出了适合你的工作职位，你却不知道如何从激烈的竞争中脱颖而出。 2、提问：面对这类问题，当时是不是觉得很沮丧？完全不知道怎样将自己更好的地方呈现给别人呢？ 3、影响：如果这些机会错失的话，可能会让你沮丧不已。俗话说，机不可失，失不再来。 4、解决：今天我带拆的这本书是《凸法则》，在本书中作者提出的，新颖、高效、给予、有用等七个法则，可以快速地帮大家在别人心目中留下良好印象，轻松搞定竞争对手客户面试官和一切你征服的人，达到一鸣惊人的效果。","ratings_count":0,"texts":[{"id":4585,"quote":"很多人在试图引起决策者注意时都容易犯一个谦逊的错误。谦逊是―个可爱的特征，不过若到了极端，就可能成为你的致命&nbsp;弱点。要知道，商业交流是一于顾客注意力的竞争。谦逊地等待别人认可你的价值，这是十分天真、理想的方式。\r\n要不要展示罕见特点，让决策者注意到你，这取决于你。你展示罕见特点的能力可以决定它会创造还是破坏你的事业。&nbsp;\r\n&nbsp;我儿子汤姆就是一个很好的例子，借以告诉读者展示自己的罕见特点如何帮你拿下梦想中的工作。汤姆和他哥哥在夏威夷毛伊岛长大。一天夜晚，天上繁星点点，我们像往常一样出去滑板散步。为什么说是滑板散步呢？我在小区的安静道路上散步，孩子们在利用他们的滑板或自行车“散步”。我问汤姆：“你长大后想做什么？”\r\n&nbsp;汤姆抬头指着天空说：“跟天上有关的什么事。“\r\n&nbsp;我们没想到汤姆有—天从弗吉尼亚理工大学毕业，专业是航空航天工程物理、天文学和数学。总而言之，我没有帮助过他写家庭作业。在毕业前的几周．汤姆留意了—下福蒙特州工作台，他不敢相信自己的眼晴，NASA在约翰逊航天中心的任务控制有―个职位空缺。还记得电影《阿波罗13》里汤姆汉克斯的角色说“休斯顿，我们来了一个麻烦”吗？没错就是电影里的那&nbsp;个任务控制。&nbsp;&nbsp;\r\n&nbsp;汤姆赶紧填好申请，让我看了一下。他的申请书让人印象深刻，不过我觉得他落了一项成就，我认为这项成就会让他的申请书更加突出。我问：“汤姆，为什么你不提一下你和你的大学团队赢得的那场国际竞争呢？关于设计去火星的有人驾驶任务的那场国际竞争。“\r\n&nbsp;&nbsp;&nbsp;猜汤姆怎么说的，他说：“可是，妈妈，写上会不会显得吹嘘了？”\r\n&nbsp;&nbsp;&nbsp;我告诉他＂汤姆，如果你真的做了，就不是吹嘘。面对你的决策者，要投其所好。他们会收到成百上千份类似的申请书，每个人都有极佳的GPA（平均成绩点数）、多个专业以及课外活动等。你需要找出自己与其他人有何不同之处，如果你得到了一些极少数人方能获得的成就，这项成就也许就能让你脱颖而出，进而让他们给你一个面试机会。“\r\n&nbsp;&nbsp;&nbsp;汤姆把那项证明加了进去，参加了面试，得到了那份工作。","explains":"\u003cp>好小伙伴们，我们已经阅读完了片段，下面进行I环节：\u003c/p>\u003cp>假如你去面试一份操作工的职位，你对面试官说：我聪明伶俐又能干，并且创意能力很强。结果呢，却得了面试官的一个白眼。反倒是，旁边那个瞅着有点呆呆傻傻的年轻人被录用了。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;你会不会觉得很疑惑呢？创意能力强，这个是你和其他人相比一个“罕见特点”，是自己的突出优势吧，但为什么面试官就是不要我呢？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;其实这就是我们将“罕见特点”的\u003cstrong>概念弄混\u003c/strong>了。当我们有求于对方时，恨不得一股脑将自己的优点全都倒出来。我们认为，自己越好，求得一份工作的可能性越大，却没有想到自己的“罕见特点”和这一份工作的匹配程度。因此，自己所要展现的“突出特点”一定是与所求目标相匹配的。\u003cbr>\u003c/p>\u003cp>创意能力很强，对操作工这个职位来讲肯定不合适。因为他们需要的是，可以机械地遵守规则并能够完成任务的人。但是如果你去面试一个广告设计工作的话，并且有自己的作品作为证明，你可能会被面试官极其欣赏。所以你的“罕见特点”一定要与你的目标相匹配，有助于目标达成的才能，或者是过去的某一段与之相关的经历均可。\u003c/p>\u003cp>在片段中给出的这个案例中，汤姆通过将自己在大学设计团队中参加的，设计去火星的有人驾驶任务的国际竞争经历，帮自己赢得了nasa公司在约翰逊航天中心的任务控制的职位空缺，实现了自己年少时期的梦想。\u003c/p>\u003cp>和大量的竞争者相比，也许汤姆并没有十分明显的优势。仅仅睡将过去设计航天器的经验，与自己所要寻求的工作结合起来，帮助自己取得了胜利。\u003c/p>\u003cp>通过这个案例，我们看过了如何通过把自己的“罕见特点”展示给对方，以实现我们的目标。\u003c/p>\u003cp>简历上我们经常见到小伙伴们这么写：我吃苦耐劳，乐于助人，积极向上……，写了一大堆，面试官不看，还让自己掉价。为什么呢？这些对于自己求职没用，不是“罕见特点”，所有人都会写，反正也没法证明。还会给面试官留下一个假大空，对简历不上心的印象。但假如换一种方式呢？乐于助人改为：参加义工活动，有义工证；支援了西部的小朋友每月200块钱等等这些可以证明的经历。\u003c/p>\u003cp>最关键的是向别人讲了这么多，得对别人有用，能给别人带来价值吧。\u003c/p>\u003cp>这个“罕见特点”就是你和其他人相比，有助于你达成目标的竞争优势。\u003c/p>\u003cp>我们到底应该怎么样建立自己和别人之间的联系呢？\u003c/p>\u003cp>\u003cstrong>（行动步骤）\u003c/strong>\u003c/p>\u003cp>一、回顾一下自己过往的经历，我们自己可以展示什么罕见特点了，突出自己的竞争优势，区别于别人的竞争优势。\u003c/p>\u003cp>二、自己过去取得的成绩有什么可以证明给决策者看呢？有什么材料或者数字可以证明自己的“罕见特点”？\u003c/p>\u003cp>三、将自己的优势与决策者建立联系。你可以向对方讲述自己能够为对方所带来的价值。\u003c/p>\u003cp>也许有的小伙伴会说，这种方法适只适用于求职吗？（适用边界条件）当然不是啦，当你与对方交情不深，并且对方手中掌握有你想要的资源，你能给对方带来一定的利益的场景下，都可以用“展现优点～证明～联系”的沟通方式。\u003c/p>","interaction":"\u003cp>拆书家提问设计：（编剧本）\u003c/p>\u003cp>&nbsp; &nbsp;请小伙伴们编一段小故事，几百字即可，设计出人物、情节变化（包含：起因、经过、结果）和你们之间的对话，其中部分对话使用“展现优点～证明～联系”技巧，可以是类似于求职、推销产品之类的场景。时间为五分钟，五分钟后我们来请小伙们分享一下他的剧本。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>\u003cstrong>学习者分享：我写的这个小故事是模拟的一个求职的场景，职位是运营专员，下面是我自己写的一个小对话。\u003c/strong>\u003c/p>\u003cp>面试官：你好，欢迎你来应聘我们公司的这个运营的职位职位，你能介绍一下你自己和其他的求职者相比，有什么更好的地方吗？\u003c/p>\u003cp>求职者：1.我带过思维导图和简笔画的小组，现在它们已经成为了我的标签，只要是我发布的简笔画，那么他们就参加。在这个打卡平台上，他们只认可我所带的训练小组。\u003c/p>\u003cp>2.我的微信头像给小伙伴们带来的冲击力也是蛮大的，在一个小组里面，只要他们看到我的头像在，小伙伴们就会申请参加相关活动。\u003c/p>\u003cp>3.最近有拆《运营之光》这本书，对于运营的知识储备比较充分。\u003c/p>\u003cp>面试官：你的意思是你已经获得了互联网用户的信赖吗？你很擅长在互联网上建立人和人之间的链接和情感的熟悉度吗？\u003c/p>\u003cp>求职者：擅长。我也比较擅长处理一些难对付的人。\u003c/p>\u003cp>面试官：我觉得你的能力挺符合我们这个职位的需求的，但是你怎么能够证明你自己呢？\u003c/p>\u003cp>求职者：提供一些微信的截图，包括他们对我的赞赏，以及平台运行者对我的认可。\u003c/p>\u003cp>面试官：你可以向我展示一下你人数最多的那个群，你是如何与小伙们进行互动的吗？\u003c/p>\u003cp>求职者：好呀，你看这是他们对我的赞赏，这是我对突发情况的一些处理。\u003c/p>\u003cp>面试官：非常满意。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1487400073000,"updated_at":1492441971000,"ria":true},{"id":1970,"topic":"潇潇荷3-2定级","learn_goal":"学完后，能够克服交谈不设防，让对话无限进行下去的行为。","remark":"","level":"TF3-2","duration":50,"status":0,"type":0,"chaishujia":{"username":"潇潇荷","city":"南京"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"学习目标:学习者在较为正式的沟通场合下，聊天不再漫无边际，而是在有限的时间内，限定聊天内容，达成沟通目的。\r\n小伙伴们大家下午好，欢迎你们来参加我的3-2定级，今天我带拆的书目是《凸法则》。\r\n1、事件场景 ： 在过去你有没有过这样的经历？遇到了某位你仰慕已久的大咖，想和他进行深入交流，却不知道从何谈起。某个你渴慕已久的企业，你想和他建立合作伙伴关系，却羞于开口。某家你特别想加入的企业，终于放出了适合你的工作职位，你却不知道如何从激烈的竞争中脱颖而出。\r\n2、提问：面对这类问题，当时是不是觉得很沮丧？完全不知道怎样将自己更好的地方呈现给别人呢？\r\n3、影响：如果这些机会错失的话，可能会让前面的准备拜拜流失。俗话说，机不可失，失不再来。\r\n4、解决：今天我带拆的这本书是《凸法则》，在本书中作者提出的，新颖、高效、给予、有用等七个法则，可以快速地帮大家在别人心目中留下良好印象，轻松搞定竞争对手客户面试官和一切你征服的人，达到一鸣惊人的效果。","ratings_count":0,"texts":[{"id":4584,"quote":"我说，我得去帮墨菲穿件“稳定背心”,她遇到暴风雨总会惊&nbsp;慌失措。\r\n里克看着我给墨菲套上衣服他问我：＂这管用吗？“\r\n”嗯，这就好比给婴儿穿上襁褓。因为婴儿感觉周边的世界无限大，所以会不安，甚至乱动。但是如果你用毯子包裹住他们，他们就感觉自己的世界是有限的，非常安全，有点像在妈妈的肚子里。墨菲就是这样，一给她穿上“稳定背心”她的精力受至限制就会安定下来。“\r\n里克开始笑了，说道：“山姆，这就是我们正在做的事情啊，我们正在为我的会议和邮件穿‘稳定背心’，裹住我们的谈话。“\r\n午餐时，里克和我进行了一次有趣的对话。他承诺一定做到“说话简练”。他说：“我们的套路对我的影响很大。如果我总是漫无目的地说．那我的谈话就一点儿范围也没有，我的沟通就是开放式的，我需要‘用襁褓裹住它’。设定适当的截止时间和更严格的范围限制，可以让我的每个字都说到点子上。”\r\n举个例子．如果我确定一共写10页纸，这就是一件‘稳定背心’，会改变我写作时的心态。问题不再是“这例子或见解能引人注目吗？”而是变成了“我是不是超出了10页纸的限制？&nbsp;&nbsp;如果超出了，肯定有些没用的内容要删除。”\r\n事实上．如果有些东西真的那么重要，即使我们没有放到文章里，人们也不会错过。\r\n听到客户对＂裹住谈话“的理解．我非常开心。一位协会主管告诉我：“我想立刻把这些告诉董事长。我们正为没人愿意参会而头疼呢，而且我也知道为什么大家都不愿意参加协会。要承担的责任实在太过模糊，人们在不知道件事要花费他们多长时间是不会答应的。也许他们厌倦了开会，会场上每个人都说个不停，却什么事情都无法确定。我要提议给时间规定也穿上件‘稳定背心’。如果我们承诺―个月只开―次会（除非―次会就开―个月的时间），那肯定有更多，愿意加入协会。如果我们做到准时开始准时结束，而且每场会议不超过90分钟，那肯能吸引更多的人。","explains":"请两位小伙伴分享一下从这个拆页中，得到的关键点。（和学习者之间的互动）\r\n学习者一:在和别人的交流中，例如开会，最好有一个时间，有时间的限制，讨论内容有明确的时间限制。\r\n学习者二：限定交流内容，使时间利用率最大化。\r\n这个案例很实用，在和别人交流时，如果自己没有明确的目的，只是漫无边际的闲扯，扯淡过后自己只是享受到了谈话的快感，打发了时间，自己却没有多少实质性的收获，自己原本打算要做的事情却被拖延了下去。\r\n在我们和他人进行交流时，如果设定适当的截止时间和严格的范围限制，会让大家觉得有安全感，需要做什么事情，可以在多长时间范围内完成做到心中有数。不管是做事还是交流我们都不会再有面对未知的恐惧感觉。用毯子裹住婴儿，给婴儿穿上了“稳定背心”，婴儿会感觉自己非常安全。给我们的谈话穿上“稳定背心”，同样的我们也会有安全感，对于接下来索要面对的一切，做到心中有数。\r\n我们应该如何给自己的谈话穿上“稳定背心”？\r\n首先：给我们这次的交流加上一个严格的时间限制。\r\n其次：限定此次交流所要讨论的话题。\r\n最后：写下希望通过这次交流可以达成的目标。\r\n互动部分；在你的过去有没有这样的经历呢？一个和你许久没有联系过的同学，有一天他突然打电话开始，从你的近况开始聊起，话题涉及你和他过去几年的经历，以及你们两个相对都比较熟悉的朋友最近怎样了，时间过去了半个小时，在即将挂电话时，他说出了自己打电话的目的，有些事情要请你帮忙。在这种情况下，你是喜欢这种长时间的寒暄最后讲明自己的来意呢，还是希望同学在简短的几句问候之后直接说明来意呢？同学的大段叙旧，对你最后作出要不要给他提供帮助的决定是否有十分重要的作用？\r\n学习者1：前期的铺垫不起作用。\r\n职场人都有开会的经历，相信在座的大家对于开会这件事是深恶痛绝。我们都认为开会在浪费大家时间的同时，没有提出什么有建设性的决策。我们只想告诉同事，你们去开会吧，回头只要告诉我我该做什么就行。有一个词语叫“开会者窘境”，在会议的过程中，最重要的决策都是在会议结束的最后1/4段时间内做出来的，前面的时间大部分都被浪费在侃大山闲聊中。还会有一个人担任控场者的角色，负责将大家的思路带回到会议主题上来。如果有人明确告诉你，会议不是无止境的拖延下去而是可以在几分钟之内结束，你会不会就没有那么抗拒了呢？\r\n如果有一个找你帮忙，他告诉你你能否帮我做一份PPT呢，是有关什么内容的，他做演讲时要用，而没有提供更为详细的信息？面对这样的请求，即使你有空闲时间，你愿意给人承诺吗？相反，如果他告诉你所有的有关PPT的文字部分、图片、表格，他已经准备好，你需要帮他放到PPT上去就好，只有十页，会花费你大概半个小时的时间。在这两种情况下，你愿意答应同事的哪种请求呢？","interaction":"\u003cp>\u003cstrong>请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分（1分表示很不符合，6分表示非常符合）\u003c/strong>\u003c/p>\u003cp>1 当我和他人聊天时，我希望没有时间限制。\u003c/p>\u003cp>2 当我和他人聊天时，我希望聊天内容没有限制。\u003c/p>\u003cp>3 当征询我的意见时，我希望向对方提出开放性的建议。\u003c/p>\u003cp>\u003cstrong>解释自测题\u003c/strong>\u003c/p>\u003cp>刚才让大家做的这个量表题目，主要目的是测试一下大家对于高效、目的明确的交流方式的期待程度。如果得分越高，则说明大家更倾向于使用随性的交流方式；得分越低的话，则说明大家倾向于使用在尽可能短的时间之内获取更高价值信息的交流方式。结合大家刚才的得分情况，说明大家对于高效的沟通方式还是十分渴求的。\u003c/p>\u003cp>\u003cstrong>【A3】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;刚才我们学习了如何给聊天穿上“安全背心”，以便我们可以高效完成交流。\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;小伙伴们正在进行30拆的便签训练，目前已经完成了二十拆的练习。接下来请大家运用给对话穿上“安全背心”的交流方式，请小伙伴们在自己的小组内讨论便签训练营可以改进的点，写在便签纸上，形成建议。\u003c/p>\u003cp>给大家几分钟的时间讨论一下，稍后请每组小组派一个代表分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>&nbsp;学习者一：\u003c/p>\u003cp>讨论时间限定：三分钟\u003c/p>\u003cp>讨论内容：便签的发放时间以及内容。\u003c/p>\u003cp>一、发放片段的时间与交作业有非常明确的时间界定，这样我对于如何安排自己的时间把握准确，让自已有更为具体的时间预估。\u003c/p>\u003cp>二、在片段发放之前，就告诉学员从哪些片段开始，就要自己写I部分的内容，让学员有心理预期。\u003c/p>\u003cp>三、在写便签之前，就对便签中所需要使用的一些技能点，有一个简要的说明。\u003c/p>\u003cp>四、导师最好可以提前公布一下点评的时间，让学员及时跟进点评内容，进行改进。\u003c/p>\u003cp>没想到我们可以在五分钟之内写出这么多东西来，很好用，尤其是在时间比较紧急的情况下。\u003c/p>\u003cp>学习二：\u003c/p>\u003cp>讨论时间限定：五分钟\u003c/p>\u003cp>讨论内容：小伙伴掉队情况以及A2追踪。\u003c/p>\u003cp>一、有些小伙伴掉队了，希望小伙伴参加之前，让小伙伴们对自己的时间进行自测。\u003c/p>\u003cp>二、对于便签训练营中掉队的小伙伴们，有明确的惩罚措施。\u003c/p>\u003cp>三、希望导师及时回馈。\u003c/p>\u003cp>四、对A2的追踪，使A2的行动可以持续进行下去。\u003c/p>\u003cp>通过采用给对话穿“安全背心”的方式，可以使小伙伴们提高时间利用率。\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家布置任务：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>当我们有问题时，总是习惯性拖延，觉得问题需要在很长一段时间之内才能得到解决。今天回去请大家做一个作业，拿出一张纸在十分钟之内将涌现在自己脑子里的困惑写下来，自己并给出解决方案。\u003c/strong>\u003c/p>\u003cp>学习者一：我的便签还没有写完，每次想到要写，就特别头痛，现在还积累了五个。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;解决：每个便签给自己半个小时的时间完成，如果写不完，就在群里发红包。剩下的五个会在一周之内完成。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1487397385000,"updated_at":1493643150000,"ria":true},{"id":1319,"topic":"使用开场白吸引别人注意力","learn_goal":"2-3","remark":"","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"太郎","city":"石家庄"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"跟随我完成本次的RIA现场场景演练、学习后，大家可以掌握一种独特的开场白方式，让你一开口说话就能吸引到对方的兴趣，从而更好的将交流进行下去。\r\n★今天分享的片段来自《凸法则》，作者山姆.洪恩是美国心理学家，这是一本风靡全球的心理学畅销书。而且是美国联邦政府沟通技巧的内训课。主要内容是高效表达自我，快速获得好感。\r\n★本书的亮点在于：“凸法则”是一种运用心理学，来高效表达自我的心理法则，它可以让你达到“知己知彼”的竞争状态，从而快速获得对方的信任和认可。\r\n★在这个信息爆炸，人人变得耐心有限的快节奏时代，如果你想在瞬间引起别人的深度注意并获得认可，“凸法则”可以帮助到你；如果你是需要被雇佣，提拔，投资，当选，签合同、理解……“凸法则”都可以带领你赢得梦想中的人生。","ratings_count":0,"texts":[{"id":3748,"quote":"\u003cp>下面就是我们创造的开场白，不但帮助凯瑟琳赢得了认同和投资，而且帮她成为《商业周刊》2010年度最有前途的社会企业家之一 。\u003c/p>\u003cp>你知道吗？现在每年接种疫苗有18亿。 \u003c/p>\u003cp>你知道吗？接种那些疫苗时，有近乎一半使用重复利用的针头。 \u003c/p>\u003cp>你知道吗？我们正在传播和延续我们试图预防的疾病。\u003c/p>\u003cp>想象一下，如果有一种针头是无痛的、一次性的，而且价格比当前的更便宜。\u003c/p>\u003cp>其实，你不用想象，我们已经创造出来了，这种针头就叫PharmaJet，正如这篇文章展示的这样…… \u003c/p>\u003cp>接着她就朝着这个方向奔去了，你被调动起来了吗？和你一样，房间里的每个人也都被调动起来了。 \u003c/p>\u003cp>让我们如实看待这个情况。PharmaJet团队过去这样开始他们的展示，解释他们是一个“皮下接种的医疗交付设备平台”。 \u003c/p>\u003cp>哎呀！那样的介绍在一开场就失去吸引力了。可是，很多人都这样开始自己的交流，废话连篇的解释让观众简直无奈或只能轻叹一声。其实，观众这时已经得出“此问题难以理解”的结论了，于是转向更有趣或更紧急的事情。凯瑟琳有竞争优势，因为在1分钟里，她已经让所有人都感到好奇，渴望对主题有更多的了解。\u003c/p>","explains":"\u003cp>【意译案例】\u003c/p>\u003cp>你知道吗？在竞争时代，你最多有60秒让你或你的项目引起面试官、客户、投资人等的兴趣。\u003c/p>\u003cp>你知道吗？面试官更在乎的，不是你有多少年的工作经验，而是你解决过的问题和你取得的成就。\u003c/p>\u003cp>你知道吗？你的简历、广告，甚至好的项目被否决，是因为你没在第一时间把最独特的优点展示出来。\u003c/p>\u003cp>想象一下，如果有一种方法，你一开口，决策者就前倾身子，抬起眉毛，被你的话题深深吸引是什么感觉?如果有300人同时竞争你梦想的职位，而你轻轻松松就脱颖而出了是什么感觉？如果你的努力能被所有的决策者、所有的机遇认可，事业扶摇直上是什么感觉？\u003c/p>\u003cp>其实，你不用想了，我们文中介绍的“凸法则”就可以告诉你立竿见影的办法。\u003c/p>\u003cp>我们来看原文中凯瑟琳的开场方式，她使用三个“你知道嘛”抛出了令人震惊的事实和现状＋“想象一下，如果……”对前三个问题做了一个饶有画面感的解决＋“其实你不用想象，我们……”引出接下来要进行的详细介绍。简短的5句话就获得了认同和投资。\u003c/p>\u003cp>我们来总结一下这个开场白方式：\u003c/p>\u003cp>首先，连续三个你知道吗+令人震惊的调查现状或是一些统计结果（可以百度）\u003c/p>\u003cp>其次，使用“想象一下，如果…”将对方带入一个情景，让对方感受这种情景的美妙（主要是前边针对三个你知道吗 问题的解决）\u003c/p>\u003cp>最后，使用“其实，你不用想象，我们…”再开始抛出自己要介绍的东西。\u003c/p>\u003cp>&nbsp;这样新颖的方式会让别人对你讲的东西更感兴趣。 \u003c/p>\u003cp>大家有没有注意到在以上我带大家拆解片段的整个过程中，使用的就是“凸法则”方式，先说了三个你知道吗，抛出了开场白的重要性，然后让大家想象一下有一种开场方式的神奇效果，最后结合原文详细介绍了凸法则方式的开场白步骤。\u003c/p>\u003cp>&nbsp;【举例】\u003c/p>\u003cp>比如说我的一位朋友毫无护肤意识，觉得又贵又看不到效果。\u003cbr>你知道嘛？据研究大学时期其实是最好的护理皮肤阶段\u003cbr>你知道嘛？芝加哥皮肤治疗博士曾表示，我们的皮肤更新周期约为28天，护肤品必须使用30天以上方可看到效果。\u003cbr>你知道嘛？尽管每个人的肤质不同，但不管你有没有钱&nbsp;，贪图便宜使用10元以下的面膜，50元以下的护肤品，那才叫真正的无用功。\u003cbr>想象一下，如果有一种护肤品，它既可以让你觉得价位适中，让你在使用一个周期后感受到光泽有亮度的皮肤，又可以让你以一个精神饱满&nbsp;充满朝气的形象出现在大家面前是什么样的感觉呢？\u003cbr>其实你不用想了，我已经发现了一个独特的品牌－－花印&nbsp;从我脸上你就可以看到其之效果…………\u003cbr>\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>大家还记得我过TF1-1介绍拆书帮时候的所使用的独特方法吗，就是我们刚刚学习的这种吸引人的兴趣开场白，现在我们同样来做一个关于拆书帮介绍的开场白演练。请大家认真听一下要演练的场景:由于你每周都会在朋友圈发表参加拆书帮的现场活动，有位小伙伴就不懂了，于是他跑来问你“你参加的这到底是啥啊？”\u003c/p>\u003cp>现在请俩人一组进行演练。一个人扮演拆书帮成员A，你该如何利用我们今天学到的开场白方式给别人完美的介绍我们周末的拆书帮活动呢？\u003c/p>\u003cp>另一个人扮演那位提问的小伙伴B，当你听了对于拆书帮活动的介绍后，你很快就被吸引了并且你想和这位拆书帮成员有进一步的交流话题，因此，你想把自己特别喜欢的东西和也和他分享，可以是你特别钟爱的某个品牌、非常好用的某款APP、非常诱人的美食……请尝试以饱满的热情，把这个东西推荐给他。\u003c/p>\u003cp>演练时间8分钟，之后我会选出俩位小伙伴为我们现场表演一下。\u003c/p>\u003cp>辉哥：文羊，最近我读书遇到好多问题，一个是书读不完，另一个是读完了也没什么效果记不住这些问题你有遇到过吗？\u003c/p>\u003cp>文羊：其实，这些问题我以前也遇到过，现在我可以给你介绍一种新的方法。 &nbsp; &nbsp;\u003c/p>\u003cp>你知道吗？据第十三次全国国民阅读调查结果显示：我国人均纸质阅读量为4.58本，而以色列达到60多本。\u003c/p>\u003cp>你知道吗？据成人教育学教授指出：我们成人学习的很大问题之一便是没时间、没精力。\u003cbr>你知道吗，为什么人们宁愿去参加一场几千几万元的现场培训而不愿意自己阅读呢？\u003cbr> \u003cbr>想象一下，如果有一种学习方法既能让我们有时间精力去阅读，提高阅读量，又能让我们的阅读质量高到可以与昂贵的现场培训相媲美，甚至超越。\u003cbr>\u003cbr>\u003c/p>\u003cp>其实，你不用想了，我们的周末线下拆书帮便可以带你体验一下什么叫做真正的阅读收获，神秘的便签拆书法尽在这里，这周末一起来体验下吧~\u003cbr> \u003cbr> \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1479293891000,"updated_at":1479293891000,"ria":true}]};